import { t, type DeepSet } from "../types";

/** Level 7 · Church Worker: the Spirit-led teaching for each lesson. */
export const DEEP: DeepSet = {
  "called-to-serve": {
    revelation: t(
      "A true call to serve is not born from wanting a position; it is born from seeing God, being undone, being cleansed, and then hearing His question.",
      "Ang tunay na pagkatawag sa paglilingkod ay hindi nagmumula sa paghahangad ng posisyon; nagmumula ito sa pagkakita sa Diyos, sa pagkadurog, sa paglilinis, at saka sa pagkarinig sa Kanyang tanong."
    ),
    mainTruth: t(
      "Isaiah saw the Lord high and lifted up, heard the seraphim cry \"Holy, holy, holy,\" and cried out, \"Woe is me!\" (Isaiah 6:1-5). Only after the burning coal touched his lips did he hear God ask, \"Whom shall I send?\" and answer, \"Here am I. Send me!\" (6:8). The risen Christ now gives leaders to equip His people for works of service (Ephesians 4:11-13), and every believer answers that call by offering his whole body as a living sacrifice (Romans 12:1-2). Ministry begins in worship, flows through cleansing, and ends in surrender.",
      "Nakita ni Isaias ang Panginoon na nakaupo sa mataas na trono, narinig ang mga serapin na sumisigaw ng \"Banal, banal, banal,\" at napasigaw siya, \"Kawawa ako!\" (Isaias 6:1-5). Pagkatapos lang dumampi ang nagbabagang baga sa kanyang labi saka niya narinig ang tanong ng Diyos, \"Sino ang Aking susuguin?\" at sumagot siya, \"Narito ako. Suguin Mo ako!\" (t. 8). Ngayon, ang nabuhay na mag-uling Cristo ay nagbibigay ng mga lider para ihanda ang Kanyang bayan sa gawain ng paglilingkod (Efeso 4:11-13), at bawat mananampalataya ay sumasagot sa tawag na iyon sa pag-aalay ng buong katawan bilang buhay na handog (Roma 12:1-2). Ang ministeryo ay nagsisimula sa pagsamba, dumadaan sa paglilinis, at nauuwi sa pagsuko."
    ),
    insight: [
      t(
        "Notice the order in Isaiah 6. God did not open with an assignment; He opened with a revelation of Himself. Many church workers burn out because they jumped straight to verse 8 without ever living in verses 1 to 7. They have a task but no vision of God, a schedule but no burning coal. When the work becomes bigger than your view of God, ministry turns into a burden instead of an offering.",
        "Pansinin ang pagkakasunod-sunod sa Isaias 6. Hindi nagsimula ang Diyos sa takdang gawain; nagsimula Siya sa pagpapakita ng Kanyang sarili. Maraming manggagawa ng simbahan ang napapagod nang husto dahil tumalon agad sila sa talatang 8 nang hindi nanatili sa talatang 1 hanggang 7. May gawain sila pero walang pangitain ng Diyos, may iskedyul pero walang nagbabagang baga. Kapag mas malaki na ang trabaho kaysa sa pagkakita mo sa Diyos, nagiging pasanin ang ministeryo sa halip na handog."
      ),
      t(
        "Notice too that God asked a question instead of drafting Isaiah. \"Whom shall I send?\" God does not need volunteers, yet He invites them, because He wants servants who say yes from a cleansed and willing heart. And Ephesians 4 reminds us that the goal of every gift is not a crowd that watches a few performers, but a body where everyone is equipped to serve. A worker who does everything alone may look faithful, but he may be robbing others of their calling.",
        "Pansinin din na nagtanong ang Diyos sa halip na basta utusan si Isaias. \"Sino ang Aking susuguin?\" Hindi kailangan ng Diyos ng boluntaryo, pero nag-aanyaya Siya, dahil gusto Niya ng mga lingkod na sumasagot ng oo mula sa nilinis at kusang puso. At ipinapaalala ng Efeso 4 na ang layunin ng bawat kaloob ay hindi isang madlang nanonood sa iilang nagtatanghal, kundi isang katawang lahat ay handang maglingkod. Ang manggagawang gumagawa ng lahat nang mag-isa ay mukhang tapat, pero baka inaagaw na niya sa iba ang kanilang pagkatawag."
      ),
    ],
    life: [
      t(
        "Think of Mang Ruben, who drove a jeepney for thirty years. Every Sunday he arrived early, swept the chapel floor, and arranged the plastic chairs before anyone else came. No one gave him a title. But one day the pastor asked why he did it, and he said, \"Pastor, when I was drunk on the road, God found me. Every chair I set up is my way of saying, 'Here I am.'\" His service did not start with a job description. It started with an encounter.",
        "Isipin si Mang Ruben, tatlumpung taon nang drayber ng dyip. Tuwing Linggo, maaga siyang dumarating, winawalis ang sahig ng kapilya, at inaayos ang mga plastik na upuan bago pa dumating ang iba. Walang nagbigay sa kanya ng titulo. Pero isang araw, tinanong siya ng pastor kung bakit niya ito ginagawa, at sabi niya, \"Pastor, noong lasing ako sa kalsada, hinanap ako ng Diyos. Bawat upuang inaayos ko ay paraan ko ng pagsasabing, 'Narito ako.'\" Hindi nagsimula sa job description ang paglilingkod niya. Nagsimula ito sa isang pakikipagtagpo."
      ),
      t(
        "Many OFWs think, \"I cannot serve; I only have one day off and I am tired.\" But Romans 12:1 does not say \"offer your free time\"; it says \"offer your bodies.\" Your call includes your work in the hospital, the household, the construction site. Serving the church on Friday is one expression of a life already laid on the altar from Saturday to Thursday.",
        "Maraming OFW ang nag-iisip, \"Hindi ako makapaglingkod; iisa lang ang day off ko at pagod pa ako.\" Pero hindi sinasabi ng Roma 12:1 na \"ialay ang libreng oras mo\"; sinasabi nitong \"ialay ang inyong katawan.\" Kasama sa pagkatawag mo ang trabaho mo sa ospital, sa bahay ng amo, sa construction site. Ang paglilingkod sa iglesia tuwing Biyernes ay isang pagpapahayag lang ng buhay na nakalatag na sa altar mula Sabado hanggang Huwebes."
      ),
    ],
    twist: t(
      "We think God calls the qualified. Isaiah's first words before his call were \"I am a man of unclean lips.\" His qualification was not his eloquence; it was his brokenness and God's cleansing. The very mouth that confessed its uncleanness became the mouth God sent to speak. In the Kingdom, the place of your deepest confession often becomes the place of your greatest commission.",
      "Akala natin, ang tinatawag ng Diyos ay ang mga kwalipikado. Ang unang sinabi ni Isaias bago siya tinawag ay \"Ako ay taong marumi ang labi.\" Ang kwalipikasyon niya ay hindi ang husay niyang magsalita; ito ay ang kanyang pagkadurog at ang paglilinis ng Diyos. Ang mismong bibig na umamin ng karumihan nito ang naging bibig na isinugo ng Diyos para magsalita. Sa Kaharian, ang lugar ng pinakamalalim mong pag-amin ay madalas nagiging lugar ng pinakamalaki mong pagsusugo."
    ),
    confirm: [
      t("Exodus 3:1-10: Moses meets God at a burning bush before he is sent to Pharaoh.", "Exodo 3:1-10: nakatagpo ni Moises ang Diyos sa nagliliyab na mababang punongkahoy bago siya isinugo kay Faraon."),
      t("Jeremiah 1:4-9: a young man says \"I cannot speak,\" and God touches his mouth.", "Jeremias 1:4-9: sabi ng binata \"Hindi ako marunong magsalita,\" at hinipo ng Diyos ang kanyang bibig."),
      t("John 21:15-17: Peter is restored with \"Do you love Me?\" before he is told \"Feed My sheep.\"", "Juan 21:15-17: ibinalik si Pedro sa tanong na \"Mahal mo ba Ako?\" bago siya inutusang \"Pakainin mo ang Aking mga tupa.\""),
      t("1 Peter 4:10: each one should use whatever gift he has received to serve others.", "1 Pedro 4:10: gamitin ng bawat isa ang kaloob na natanggap niya upang maglingkod sa iba."),
    ],
    heart: [
      t(
        "Move from seeking a role to seeking the Lord. Positions can be given and taken away, but a heart that has seen God will keep saying \"Here am I\" even when no one is watching.",
        "Lumipat mula sa paghahanap ng posisyon tungo sa paghahanap sa Panginoon. Ang posisyon ay maibibigay at mababawi, pero ang pusong nakakita sa Diyos ay patuloy na magsasabing \"Narito ako\" kahit walang nakatingin."
      ),
      t(
        "Let your service become an equipping service. Measure your ministry not only by what you do, but by how many others you help to serve.",
        "Hayaang maging paglilingkod na nagsasanay ang iyong paglilingkod. Sukatin ang ministeryo mo hindi lang sa kung ano ang ginagawa mo, kundi sa kung ilan ang natutulungan mong maglingkod din."
      ),
    ],
    questions: [
      t("When did you last have a fresh sight of God's holiness, not just a new task to do?", "Kailan ka huling nagkaroon ng sariwang pagkakita sa kabanalan ng Diyos, hindi lang bagong gawain?"),
      t("Is there an \"unclean lip\" in your life you need to bring to God before you serve again?", "May \"maruming labi\" ba sa buhay mo na kailangan mong dalhin sa Diyos bago ka muling maglingkod?"),
      t("Are you serving because you were moved by God or because you were pressured by people?", "Naglilingkod ka ba dahil inudyukan ka ng Diyos o dahil pinilit ka ng tao?"),
      t("Who is one person you can begin to equip instead of doing the work for them?", "Sino ang isang taong puwede mong simulang sanayin sa halip na ikaw ang gumawa para sa kanya?"),
    ],
    actions: [
      t("Read Isaiah 6:1-8 slowly tonight and spend five minutes in silent worship before you ask God for anything.", "Basahin nang dahan-dahan ang Isaias 6:1-8 ngayong gabi at gumugol ng limang minuto sa tahimik na pagsamba bago ka humiling ng anuman sa Diyos."),
      t("Write your call story on one page: how God found you, cleansed you, and stirred you to serve.", "Isulat sa isang pahina ang kuwento ng pagkatawag mo: paano ka hinanap ng Diyos, nilinis, at inudyukang maglingkod."),
      t("Invite one newer believer to help you in your ministry task this week, and explain why you do it.", "Anyayahan ang isang mas bagong mananampalataya na tumulong sa iyong gawain ngayong linggo, at ipaliwanag kung bakit mo ito ginagawa."),
    ],
    prayer: t(
      "Holy Lord, high and lifted up, I have seen how small I am and how great You are. I confess my unclean lips and my mixed motives. Touch me again with the fire of Your altar and cleanse me. I do not ask for a title; I ask for Your presence. I offer You my body, my time, my strength, my work abroad and my rest. Here am I, Lord. Send me, and make me a servant who helps others serve. In Jesus' name, Amen.",
      "Banal na Panginoon, mataas at dakila, nakita ko kung gaano ako kaliit at kung gaano Ka kadakila. Ipinagtatapat ko ang marumi kong labi at ang halo-halo kong motibo. Hipuin Mo akong muli ng apoy ng Iyong altar at linisin Mo ako. Hindi titulo ang hinihingi ko; ang Iyong presensya ang hinihingi ko. Iniaalay ko sa Iyo ang aking katawan, oras, lakas, trabaho sa abroad at pahinga. Narito ako, Panginoon. Suguin Mo ako, at gawin Mo akong lingkod na tumutulong sa iba na maglingkod. Sa pangalan ni Hesus, Amen."
    ),
  },

  "serving-with-excellence": {
    revelation: t(
      "Excellence and humility are not rivals; they are two hands of the same servant, one doing its best and the other giving God the credit.",
      "Ang kahusayan at kababaang-loob ay hindi magkaaway; sila ay dalawang kamay ng iisang lingkod, ang isa ay ginagawa ang pinakamabuti at ang isa ay ibinibigay sa Diyos ang papuri."
    ),
    mainTruth: t(
      "\"Whatever you do, work at it with all your heart, as working for the Lord, not for human masters\" (Colossians 3:23-24). That is the call to excellence. \"In humility value others above yourselves\" (Philippians 2:3), with the mind of Christ, who though He was God \"made Himself nothing, taking the very nature of a servant\" (2:6-8). That is the call to humility. Nehemiah's builders show both together: \"the people worked with all their heart\" (Nehemiah 4:6), each one on his own section of the wall, with no one claiming the whole wall as his own.",
      "\"Anuman ang inyong gawin, gawin ninyo nang buong puso, na parang sa Panginoon at hindi sa tao\" (Colosas 3:23-24). Iyan ang tawag sa kahusayan. \"Sa kababaang-loob, ituring ninyong higit ang iba kaysa sa inyong sarili\" (Filipos 2:3), taglay ang pag-iisip ni Cristo, na kahit Diyos ay \"hinubad ang lahat at nag-anyong alipin\" (t. 6-8). Iyan ang tawag sa kababaang-loob. Ipinapakita ng mga nagtayo kasama ni Nehemias ang dalawang ito nang sabay: \"buong puso ang paggawa ng mga tao\" (Nehemias 4:6), bawat isa sa kanyang sariling bahagi ng pader, at walang umangkin na kanya ang buong pader."
    ),
    insight: [
      t(
        "Many believers think \"It's just for church\" excuses sloppiness: arriving late, preparing the lesson in the jeep on the way, leaving the chairs for someone else. But Colossians 3 was written to slaves doing ordinary chores. If God deserves excellence in a kitchen, how much more in His house? Carelessness in small things quietly tells people that God is not worth much effort.",
        "Maraming mananampalataya ang nag-iisip na \"Pang-simbahan lang naman\" kaya puwede nang pabaya: late dumating, inihahanda ang aralin sa dyip papunta, iniiwan ang mga upuan para sa iba. Pero ang Colosas 3 ay isinulat para sa mga aliping gumagawa ng karaniwang gawain. Kung karapat-dapat ang Diyos sa kahusayan sa kusina, gaano pa kaya sa Kanyang bahay? Ang kapabayaan sa maliliit na bagay ay tahimik na nagsasabi sa tao na hindi sulit pagsikapan ang Diyos."
      ),
      t(
        "Yet there is a hidden danger on the other side. Excellence without humility turns ministry into a stage. The worship leader who must be praised, the usher who sulks when not thanked, the teacher who cannot accept correction: all of them may be skilled, but their skill is serving self. Jesus did the most excellent work in history, and He did it with a towel around His waist.",
        "Pero may nakatagong panganib sa kabilang panig. Ang kahusayang walang kababaang-loob ay ginagawang entablado ang ministeryo. Ang worship leader na kailangang purihin, ang usher na nagtatampo kapag hindi napasalamatan, ang guro na hindi matanggap ang pagtutuwid: maaaring magaling silang lahat, pero ang kanilang galing ay naglilingkod sa sarili. Ginawa ni Hesus ang pinakamahusay na gawain sa kasaysayan, at ginawa Niya ito nang may tuwalyang nakatali sa baywang."
      ),
    ],
    life: [
      t(
        "Ate Lorna works as a caregiver in Dubai. Her employer once said, \"Why do you clean even the corners I never check?\" She smiled and said, \"Because Someone else checks.\" When the family later asked about her faith, it was not her preaching that opened the door; it was the way she folded towels. Excellence in hidden places is a sermon that people can see.",
        "Si Ate Lorna ay caregiver sa Dubai. Minsan sabi ng amo niya, \"Bakit pati mga sulok na hindi ko naman tinitingnan ay nililinis mo?\" Ngumiti siya at sinabing, \"Kasi may Iba pong tumitingin.\" Nang magtanong kalaunan ang pamilya tungkol sa pananampalataya niya, hindi ang pangangaral niya ang nagbukas ng pinto; ang paraan niya ng pagtiklop ng tuwalya. Ang kahusayan sa mga tagong lugar ay sermong nakikita ng tao."
      ),
      t(
        "In church, it looks like a sound technician who tests the mic before the guests arrive, a teacher who prepares on Wednesday, not Sunday morning, and a cell leader who finishes the follow-up he promised. And humility looks like the same people quietly clapping for someone else's idea, and asking, \"How can I do this better?\"",
        "Sa iglesia, ganito ang itsura nito: ang sound technician na tinetesting ang mic bago dumating ang mga bisita, ang guro na naghahanda tuwing Miyerkules at hindi Linggo ng umaga, at ang cell leader na tinatapos ang follow-up na ipinangako niya. At ang kababaang-loob ay ganito: ang parehong mga taong iyon ay tahimik na pumapalakpak sa ideya ng iba, at nagtatanong, \"Paano ko pa ito mapagbubuti?\""
      ),
    ],
    twist: t(
      "We think humility means doing less so we will not be noticed. But Jesus did not lower His standard when He humbled Himself; He went all the way to the cross. True humility is not mediocre effort; it is full effort with no need for applause. The humblest servant in the room is often the one working hardest, because he has nothing to prove and Someone to please.",
      "Akala natin ang kababaang-loob ay paggawa nang kaunti para hindi mapansin. Pero hindi ibinaba ni Hesus ang pamantayan Niya nang magpakababa Siya; tinahak Niya ang daan hanggang krus. Ang tunay na kababaang-loob ay hindi pagsisikap na pwede na; ito ay buong pagsisikap na hindi naghahanap ng palakpak. Ang pinakamapagpakumbabang lingkod sa silid ay madalas ang pinakamasipag, dahil wala na siyang kailangang patunayan at may Isang gusto niyang mapalugdan."
    ),
    confirm: [
      t("Exodus 35:30-35: Bezalel is filled with the Spirit for skilled, careful craftsmanship.", "Exodo 35:30-35: napuspos ng Espiritu si Bezalel para sa mahusay at maingat na paggawa."),
      t("John 13:3-5: knowing all authority was His, Jesus took a towel and washed feet.", "Juan 13:3-5: alam ni Hesus na Kanya ang lahat ng kapangyarihan, pero kumuha Siya ng tuwalya at naghugas ng paa."),
      t("Proverbs 22:29: a man skilled in his work will serve before kings.", "Kawikaan 22:29: ang taong mahusay sa kanyang gawain ay maglilingkod sa harap ng mga hari."),
      t("1 Peter 5:5-6: clothe yourselves with humility, and God will lift you up in due time.", "1 Pedro 5:5-6: magbihis kayo ng kababaang-loob, at itataas kayo ng Diyos sa takdang panahon."),
    ],
    heart: [
      t(
        "Let go of \"Pwede na 'yan\" thinking in God's work. Give Him your first and best, not your leftovers and last-minute effort.",
        "Bitawan ang \"Pwede na 'yan\" na pag-iisip sa gawain ng Diyos. Ibigay sa Kanya ang una at pinakamabuti mo, hindi ang tira at huling-minutong pagsisikap."
      ),
      t(
        "At the same time, let go of the need to be noticed. Do your section of the wall well, and rejoice when someone else's section looks better than yours.",
        "Kasabay nito, bitawan ang pangangailangang mapansin. Gawin nang mahusay ang bahagi mo ng pader, at magalak kapag mas maganda ang bahagi ng iba kaysa sa iyo."
      ),
    ],
    questions: [
      t("Where do you most often cut corners in your ministry, and why?", "Saan ka pinakamadalas nagpapabaya sa iyong ministeryo, at bakit?"),
      t("How do you honestly feel when someone else gets the credit for work you did?", "Ano ang tapat mong nararamdaman kapag iba ang napupuri sa gawaing ikaw ang gumawa?"),
      t("Can you receive correction about your service without becoming defensive?", "Kaya mo bang tanggapin ang pagtutuwid tungkol sa iyong paglilingkod nang hindi nagiging depensibo?"),
      t("If Jesus were your only audience this Sunday, what would you do differently?", "Kung si Hesus lang ang manonood mo ngayong Linggo, ano ang gagawin mong iba?"),
    ],
    actions: [
      t("Choose one area of your service (preparation, punctuality or follow-through) and raise it one level this week.", "Pumili ng isang bahagi ng iyong paglilingkod (paghahanda, pagdating sa oras o pagtatapos ng sinimulan) at itaas ito ng isang antas ngayong linggo."),
      t("Ask a leader, \"What is one thing I can do better?\" and thank them for the answer.", "Tanungin ang isang lider, \"Ano ang isang bagay na mapagbubuti ko pa?\" at pasalamatan siya sa sagot."),
      t("Publicly thank someone whose hidden work made this Sunday's service possible.", "Pasalamatan sa harap ng iba ang isang taong ang tagong gawain ang nagpatakbo ng serbisyo ngayong Linggo."),
    ],
    prayer: t(
      "Lord Jesus, You did everything well, and You did it as a servant. Forgive me for the times I gave You my leftovers, and for the times I wanted the praise that belongs to You. Teach me to work with all my heart, as for You and not for people. Keep my hands diligent and my heart low. Let my best be an offering, and let my reward be Your smile. In Your name, Amen.",
      "Panginoong Hesus, mahusay Mong ginawa ang lahat, at ginawa Mo ito bilang lingkod. Patawarin Mo ako sa mga panahong tira-tira ang ibinigay ko sa Iyo, at sa mga panahong hinangad ko ang papuring para sa Iyo. Turuan Mo akong gumawa nang buong puso, para sa Iyo at hindi para sa tao. Panatilihin Mong masipag ang aking mga kamay at mapagpakumbaba ang aking puso. Nawa'y maging handog ang pinakamabuti ko, at ang ngiti Mo ang aking gantimpala. Sa Iyong pangalan, Amen."
    ),
  },

  "sound-doctrine": {
    revelation: t(
      "Sound doctrine is not cold information for debaters; it is healthy food that keeps God's flock alive, and every church worker is a guardian at the kitchen door.",
      "Ang tamang aral ay hindi malamig na impormasyon para sa mga mahilig makipagtalo; ito ay malusog na pagkain na bumubuhay sa kawan ng Diyos, at bawat manggagawa ng simbahan ay bantay sa pinto ng kusina."
    ),
    mainTruth: t(
      "Paul's final charge to Timothy was solemn: \"Preach the word... For the time will come when people will not put up with sound doctrine. Instead, to suit their own desires, they will gather around them a great number of teachers to say what their itching ears want to hear\" (2 Timothy 4:1-4). To the Ephesian elders he warned, \"Savage wolves will come in among you\" and even \"from your own number\" (Acts 20:28-31). That is why a leader \"must hold firmly to the trustworthy message as it has been taught, so that he can encourage others by sound doctrine and refute those who oppose it\" (Titus 1:9). The word \"sound\" means healthy. Truth is not only right; it heals.",
      "Seryoso ang huling bilin ni Pablo kay Timoteo: \"Ipangaral mo ang Salita... Sapagkat darating ang panahon na hindi na titiisin ng mga tao ang tamang aral. Sa halip, ayon sa sarili nilang hilig, mag-iipon sila ng maraming guro na magsasabi ng gustong marinig ng kanilang makating tainga\" (2 Timoteo 4:1-4). Sa mga matanda sa Efeso, nagbabala siya, \"Papasok sa inyo ang mababangis na lobo,\" at manggagaling pa nga ang ilan \"sa inyong sarili\" (Gawa 20:28-31). Kaya ang isang lider ay \"dapat matatag na nanghahawak sa mapagkakatiwalaang aral na itinuro sa kanya, upang mapalakas niya ang iba sa pamamagitan ng tamang aral at maituwid ang mga sumasalungat\" (Tito 1:9). Ang ibig sabihin ng \"tamang\" dito ay malusog. Ang katotohanan ay hindi lang tama; nagpapagaling ito."
    ),
    insight: [
      t(
        "Notice where Paul locates the problem: not only in the false teachers but in \"itching ears.\" False doctrine thrives because there is a market for it. People want a gospel without a cross, blessing without obedience, a Jesus who serves their plans. The first line of defense is not only spotting wolves outside; it is examining whether my own heart prefers comfortable lies to hard truth.",
        "Pansinin kung saan inilagay ni Pablo ang problema: hindi lang sa mga bulaang guro kundi sa \"makating tainga.\" Lumalago ang maling aral dahil may bumibili nito. Gusto ng tao ng ebanghelyong walang krus, pagpapalang walang pagsunod, isang Hesus na naglilingkod sa sarili nilang plano. Ang unang depensa ay hindi lang ang pagkilala sa mga lobo sa labas; ito ay ang pagsusuri kung mas gusto ba ng sarili kong puso ang komportableng kasinungalingan kaysa sa mahirap na katotohanan."
      ),
      t(
        "Notice also that Paul tells Timothy to do this \"with great patience and careful instruction\" (2 Timothy 4:2). Guarding doctrine is not about winning arguments in the comments section. Many who are deceived are sheep, not wolves. A church worker guards truth best by knowing the essentials well (one God in three Persons, Jesus fully God and fully man, salvation by grace through faith, the authority of Scripture, Christ's return) and by teaching them with gentleness.",
        "Pansinin din na sinabi ni Pablo kay Timoteo na gawin ito \"nang may lubos na pagtitiyaga at maingat na pagtuturo\" (2 Timoteo 4:2). Ang pag-iingat sa aral ay hindi tungkol sa pananalo sa debate sa comments section. Marami sa nalinlang ay tupa, hindi lobo. Pinakamahusay na nababantayan ng manggagawa ang katotohanan kapag kilala niyang mabuti ang mga pangunahing aral (iisang Diyos sa tatlong Persona, si Hesus na ganap na Diyos at ganap na tao, kaligtasan sa biyaya sa pamamagitan ng pananampalataya, ang awtoridad ng Kasulatan, ang pagbabalik ni Cristo) at kapag itinuturo niya ito nang may kahinahunan."
      ),
    ],
    life: [
      t(
        "Bank tellers are not trained by studying every kind of fake money. They are trained by handling real bills again and again until a fake feels wrong in their fingers. The same is true for us. A church worker who knows the real gospel deeply will sense the counterfeit, whether it is a preacher on social media promising \"guaranteed wealth if you sow today,\" or a friend saying \"all religions are the same.\"",
        "Hindi sinasanay ang mga bank teller sa pag-aaral ng lahat ng uri ng pekeng pera. Sinasanay sila sa paghawak ng tunay na pera nang paulit-ulit hanggang sa maramdaman agad ng kanilang daliri kapag peke. Ganoon din tayo. Ang manggagawang lubos na kilala ang tunay na ebanghelyo ay makakaramdam ng peke, maging ito ay isang mangangaral sa social media na nangangako ng \"siguradong yaman kapag nag-seed ka ngayon,\" o isang kaibigang nagsasabing \"pare-pareho lang ang lahat ng relihiyon.\""
      ),
      t(
        "In OFW fellowships, new teachings travel fast through group chats. A forwarded video can unsettle a whole cell group overnight. A wise worker does not panic or mock. He says, \"Let us open the Bible together,\" and if needed, \"Let us ask our pastor.\" That simple habit has protected many young believers from being carried away.",
        "Sa mga OFW fellowship, mabilis kumalat ang bagong aral sa group chat. Isang na-forward na video ay kayang guluhin ang buong cell group sa isang gabi lang. Ang matalinong manggagawa ay hindi nagpapanic o nangungutya. Sinasabi niya, \"Buksan natin ang Bibliya nang sama-sama,\" at kung kailangan, \"Itanong natin sa pastor natin.\" Ang simpleng ugaling iyan ay nakapagligtas na sa maraming batang mananampalataya na matangay."
      ),
    ],
    twist: t(
      "We imagine the greatest threat to the church is the teacher who openly denies Christ. But Paul said the wolves would rise \"from your own number,\" speaking almost-true things. Most error is not a total lie; it is a truth pushed out of its place, like grace without repentance, or faith without love. The best guard against error is not suspicion of everyone but a deep, balanced love for the whole counsel of God.",
      "Akala natin ang pinakamalaking banta sa iglesia ay ang gurong hayagang tumatanggi kay Cristo. Pero sabi ni Pablo, ang mga lobo ay lilitaw \"mula sa inyong sarili,\" nagsasabi ng mga bagay na halos totoo. Ang karamihan sa mali ay hindi buong kasinungalingan; ito ay katotohanang inalis sa tamang lugar, gaya ng biyayang walang pagsisisi, o pananampalatayang walang pag-ibig. Ang pinakamahusay na bantay laban sa mali ay hindi ang paghihinala sa lahat kundi ang malalim at balanseng pag-ibig sa buong kalooban ng Diyos."
    ),
    confirm: [
      t("Acts 17:11: the Bereans examined the Scriptures daily to see if Paul's words were true.", "Gawa 17:11: araw-araw sinuri ng mga taga-Berea ang Kasulatan kung totoo ang sinasabi ni Pablo."),
      t("Galatians 1:6-9: even an angel preaching another gospel is to be rejected.", "Galacia 1:6-9: kahit anghel na nangangaral ng ibang ebanghelyo ay dapat tanggihan."),
      t("1 John 4:1-3: test the spirits by what they confess about Jesus Christ.", "1 Juan 4:1-3: subukin ang mga espiritu ayon sa ipinapahayag nila tungkol kay Hesu-Cristo."),
      t("Jude 1:3: contend for the faith once for all delivered to the saints.", "Judas 1:3: ipaglaban ang pananampalatayang minsanang ibinigay sa mga banal."),
    ],
    heart: [
      t(
        "Cultivate a love for truth, not just a love for being right. Ask God to make your ears healthy, so that you crave what is true even when it confronts you.",
        "Linangin ang pag-ibig sa katotohanan, hindi lang ang pag-ibig na maging tama. Hilingin sa Diyos na gawing malusog ang iyong tainga, para hangarin mo ang totoo kahit sinasaway ka nito."
      ),
      t(
        "Guard the flock with a shepherd's heart. Be firm on the essentials, gracious on secondary matters, and gentle with the confused.",
        "Bantayan ang kawan nang may puso ng pastol. Maging matatag sa mga pangunahing aral, mapagbiyaya sa mga pangalawang usapin, at mahinahon sa mga nalilito."
      ),
    ],
    questions: [
      t("Could you explain the gospel and the Trinity from the Bible to a new believer?", "Kaya mo bang ipaliwanag mula sa Bibliya ang ebanghelyo at ang Trinidad sa isang bagong mananampalataya?"),
      t("Which teachings do you enjoy only because they are comfortable to hear?", "Aling mga aral ang gusto mo lang dahil komportable itong pakinggan?"),
      t("What false teachings are spreading among the people you serve?", "Anong mga maling aral ang kumakalat sa mga taong pinaglilingkuran mo?"),
      t("When you correct someone, do they feel your love or only your argument?", "Kapag nagtutuwid ka, nararamdaman ba nila ang pagmamahal mo o ang argumento mo lang?"),
    ],
    actions: [
      t("Ask your pastor for your church's statement of faith and read it this week with the Bible references open.", "Hingin sa pastor ang statement of faith ng inyong iglesia at basahin ito ngayong linggo kasama ang mga talata sa Bibliya."),
      t("Memorize one verse for each essential: Matthew 28:19, John 1:1, Ephesians 2:8-9, 2 Timothy 3:16.", "Isaulo ang isang talata para sa bawat pangunahing aral: Mateo 28:19, Juan 1:1, Efeso 2:8-9, 2 Timoteo 3:16."),
      t("Before sharing any teaching video in a group chat, check it against Scripture or ask a leader first.", "Bago mag-share ng anumang teaching video sa group chat, suriin muna ito ayon sa Kasulatan o magtanong muna sa isang lider."),
    ],
    prayer: t(
      "Father, Your word is truth, and I want to love it more than my own comfort. Heal any itching in my ears. Give me a deep grasp of the gospel so that I can recognize what is false, and give me a gentle heart so that I can lead the confused back to You. Protect Your flock from wolves, and keep me from ever becoming one. Make me a faithful guardian of what You have entrusted. In Jesus' name, Amen.",
      "Ama, ang Iyong Salita ay katotohanan, at gusto kong mahalin ito nang higit sa sarili kong ginhawa. Pagalingin Mo ang anumang pangangati ng aking tainga. Bigyan Mo ako ng malalim na pagkaunawa sa ebanghelyo para makilala ko ang huwad, at bigyan Mo ako ng mahinahong puso para maibalik ko sa Iyo ang mga nalilito. Ingatan Mo ang Iyong kawan sa mga lobo, at huwag Mong hayaang maging isa ako sa kanila. Gawin Mo akong tapat na bantay sa ipinagkatiwala Mo. Sa pangalan ni Hesus, Amen."
    ),
  },

  "visitation-and-care": {
    revelation: t(
      "When you walk into a hospital room or a poor family's home, you are not only bringing Jesus there; you are meeting Jesus there.",
      "Kapag pumasok ka sa kuwarto ng ospital o sa tahanan ng mahirap na pamilya, hindi mo lang dinadala si Hesus doon; doon mo rin Siya nakakatagpo."
    ),
    mainTruth: t(
      "In the parable of the sheep and the goats, the King says, \"I was sick and you looked after me... whatever you did for one of the least of these brothers and sisters of mine, you did for me\" (Matthew 25:36, 40). James defines religion God accepts as this: \"to look after orphans and widows in their distress and to keep oneself from being polluted by the world\" (James 1:27). And when someone is sick, the elders are called to come and pray over him (James 5:14-15). Care for the hurting is not an extra program; it is the heartbeat of a church that knows its King.",
      "Sa talinghaga ng mga tupa at kambing, sabi ng Hari, \"Ako'y nagkasakit at inalagaan ninyo Ako... anumang ginawa ninyo sa isa sa pinakamaliit sa Aking mga kapatid, sa Akin ninyo ginawa\" (Mateo 25:36, 40). Ganito inilarawan ni Santiago ang relihiyong tinatanggap ng Diyos: \"ang pagdalaw sa mga ulila at mga balo sa kanilang kapighatian at ang pag-iingat sa sarili na hindi madungisan ng sanlibutan\" (Santiago 1:27). At kapag may maysakit, tinatawag ang mga matanda na pumunta at ipanalangin siya (Santiago 5:14-15). Ang pag-aalaga sa nasasaktan ay hindi dagdag na programa; ito ang tibok ng puso ng iglesiang kilala ang kanyang Hari."
    ),
    insight: [
      t(
        "What surprised both groups in Matthew 25 was that they did not know. The righteous asked, \"When did we see You sick?\" They were not visiting for points; they simply loved. And the others were not judged for doing evil, but for doing nothing. Many good church people will not be surprised by what they did wrong, but by the people they walked past.",
        "Ang ikinagulat ng dalawang grupo sa Mateo 25 ay hindi nila alam. Nagtanong ang mga matuwid, \"Kailan Ka namin nakitang maysakit?\" Hindi sila dumadalaw para makakuha ng puntos; nagmamahal lang sila. At ang iba ay hinatulan hindi dahil gumawa sila ng masama, kundi dahil wala silang ginawa. Maraming mabubuting taong-simbahan ang magugulat hindi sa mali nilang ginawa, kundi sa mga taong nilampasan nila."
      ),
      t(
        "We also overlook that the ministry of care is mostly presence, not performance. People in pain rarely remember the sermon you preached at their bedside. They remember that you came, that you sat down, that you listened, that you prayed, and that you came back. A short visit with a psalm and a prayer can carry more of heaven than an hour of advice.",
        "Nakakaligtaan din natin na ang ministeryo ng pag-aalaga ay higit sa lahat presensya, hindi pagtatanghal. Bihirang maalala ng taong nasasaktan ang sermong ipinangaral mo sa tabi ng kama niya. Naaalala nila na dumating ka, na umupo ka, na nakinig ka, na nanalangin ka, at na bumalik ka. Ang maikling pagdalaw na may isang awit at panalangin ay kayang magdala ng higit na langit kaysa sa isang oras na payo."
      ),
    ],
    life: [
      t(
        "A domestic helper in Kuwait broke her arm and was sent to a hospital where she knew no one. On her second night, two sisters from the fellowship came with lugaw, a phone charger and a small Bible. They stayed only twenty minutes. Years later she said, \"That was the night I knew Jesus was real, because His people found me.\" They did not preach a long message. They simply showed up.",
        "Isang kasambahay sa Kuwait ang nabalian ng braso at dinala sa ospital kung saan wala siyang kakilala. Sa ikalawang gabi, dumating ang dalawang kapatid mula sa fellowship na may dalang lugaw, charger ng cellphone at maliit na Bibliya. Dalawampung minuto lang sila nanatili. Makalipas ang ilang taon, sabi niya, \"Iyon ang gabing nalaman kong totoo si Hesus, dahil hinanap ako ng Kanyang bayan.\" Hindi sila nangaral nang mahaba. Dumating lang sila."
      ),
      t(
        "Care also has hands. Sometimes the most spiritual thing you can do for a struggling family is pay their electric bill, bring rice, help a widow fill out her SSS papers, or call an OFW's elderly mother in the province when he cannot go home. Respect privacy, avoid gossip about who needs help, and bring serious matters to the pastor.",
        "May kamay din ang pag-aalaga. Minsan, ang pinakaespirituwal na magagawa mo para sa nahihirapang pamilya ay bayaran ang kuryente nila, magdala ng bigas, tulungan ang isang biyuda sa mga papeles niya sa SSS, o tawagan ang matandang nanay ng isang OFW sa probinsya kapag hindi siya makauwi. Igalang ang privacy, iwasan ang tsismis tungkol sa kung sino ang tinutulungan, at dalhin sa pastor ang mabibigat na usapin."
      ),
    ],
    twist: t(
      "We go to the sick thinking we are the strong ones bringing Christ to the weak. But Jesus said, \"You did it to Me.\" The poor and the sick are not only objects of our ministry; they are places where Christ hides Himself to be met. The visitor often leaves more blessed than the visited, because he has just been in the presence of his Lord in disguise.",
      "Pumupunta tayo sa maysakit na iniisip na tayo ang malakas na nagdadala ng Cristo sa mahina. Pero sabi ni Hesus, \"Sa Akin ninyo ginawa.\" Ang mahihirap at maysakit ay hindi lang tumatanggap ng ating ministeryo; sila ang mga lugar kung saan nagtatago si Cristo para makatagpo natin. Madalas, mas pinagpala ang dumadalaw kaysa sa dinadalaw, dahil kagagaling lang niya sa presensya ng kanyang Panginoon na nakabalatkayo."
    ),
    confirm: [
      t("Luke 10:33-35: the Samaritan stopped, bandaged, carried and paid for a stranger.", "Lucas 10:33-35: huminto ang Samaritano, binendahan, binuhat at binayaran ang gastos ng isang estranghero."),
      t("Job 2:11-13: Job's friends did best when they sat with him silently for seven days.", "Job 2:11-13: pinakamabuti ang ginawa ng mga kaibigan ni Job nang tahimik silang umupo kasama niya nang pitong araw."),
      t("Acts 9:36-39: Dorcas was mourned by widows wearing the clothes she had made for them.", "Gawa 9:36-39: iniyakan si Dorcas ng mga balong suot ang mga damit na ginawa niya para sa kanila."),
      t("2 Timothy 1:16-17: Onesiphorus searched for Paul in Rome until he found him.", "2 Timoteo 1:16-17: hinanap ni Onesiforo si Pablo sa Roma hanggang matagpuan siya."),
    ],
    heart: [
      t(
        "Trade awkwardness for compassion. You do not need perfect words; you need a willing heart and a few minutes. Your presence is the message.",
        "Ipagpalit ang pagkailang sa malasakit. Hindi mo kailangan ng perpektong salita; kailangan mo ng kusang puso at ilang minuto. Ang presensya mo ang mensahe."
      ),
      t(
        "Learn to see Christ in the least. Let the unnoticed person in your church become the person you notice first.",
        "Matutong makita si Cristo sa pinakamaliit. Hayaang ang hindi napapansing tao sa iglesia ang maging unang mapansin mo."
      ),
    ],
    questions: [
      t("Who in your church or group is sick, grieving or struggling right now, and who has visited them?", "Sino sa inyong iglesia o grupo ang maysakit, nagdadalamhati o nahihirapan ngayon, at sino na ang dumalaw sa kanila?"),
      t("What makes visiting hard for you: fear, busyness, or not knowing what to say?", "Ano ang nagpapahirap sa iyo sa pagdalaw: takot, kaabalahan, o hindi alam ang sasabihin?"),
      t("If Jesus were the one in that hospital bed, would you still be too busy?", "Kung si Hesus ang nasa kama ng ospital na iyon, abala ka pa rin ba?"),
      t("How can your group care in practical ways, not only with \"I'll pray for you\"?", "Paano makapag-aalaga ang inyong grupo sa praktikal na paraan, hindi lang sa \"Ipagdarasal kita\"?"),
    ],
    actions: [
      t("Visit, or video call, one sick or grieving person this week. Keep it short, listen, read a psalm and pray.", "Dalawin, o i-video call, ang isang maysakit o nagdadalamhati ngayong linggo. Gawing maikli, makinig, magbasa ng isang awit at manalangin."),
      t("Meet one practical need quietly: food, a bill, a ride to the clinic, or help with papers.", "Tugunan nang tahimik ang isang praktikal na pangangailangan: pagkain, bayarin, sakay papuntang klinika, o tulong sa papeles."),
      t("Start a simple care list with your leader so no member in need is forgotten.", "Magsimula ng simpleng care list kasama ang iyong lider para walang miyembrong nangangailangan ang makalimutan."),
    ],
    prayer: t(
      "Lord Jesus, You came near to the sick, the poor and the forgotten, and You still wait for me in them. Forgive me for the times I walked past. Give me eyes to see who is hurting and courage to show up even when I do not know what to say. Let my visits carry Your peace, my hands carry Your kindness, and my prayers carry Your power. When I serve the least, let me know I am serving You. In Your name, Amen.",
      "Panginoong Hesus, lumapit Ka sa maysakit, sa mahirap at sa nakalimutan, at hinihintay Mo pa rin ako sa kanila. Patawarin Mo ako sa mga panahong nilampasan ko sila. Bigyan Mo ako ng matang nakakakita kung sino ang nasasaktan at ng lakas ng loob na pumunta kahit hindi ko alam ang sasabihin. Nawa'y madala ng aking pagdalaw ang Iyong kapayapaan, ng aking mga kamay ang Iyong kabutihan, at ng aking mga panalangin ang Iyong kapangyarihan. Kapag pinaglilingkuran ko ang pinakamaliit, ipaalala Mong Ikaw ang pinaglilingkuran ko. Sa Iyong pangalan, Amen."
    ),
  },

  "guarding-your-heart": {
    revelation: t(
      "God cares about the servant, not only the service; before He sends you out again, He wants to feed you, rest you and meet you.",
      "Mahalaga sa Diyos ang lingkod, hindi lang ang paglilingkod; bago ka Niya isugo muli, gusto ka Niyang pakainin, pagpahingahin at katagpuin."
    ),
    mainTruth: t(
      "Right after fire fell on Mount Carmel, Elijah ran from Jezebel, sat under a broom bush and prayed to die (1 Kings 19:1-4). God did not rebuke him. An angel touched him and said, \"Get up and eat, for the journey is too much for you\" (19:5-7), and only later did God speak in a gentle whisper. When the apostles returned excited from ministry, Jesus said, \"Come with me by yourselves to a quiet place and get some rest\" (Mark 6:31). And Proverbs 4:23 commands, \"Above all else, guard your heart, for everything you do flows from it.\" Your ministry can only be as healthy as the heart it flows from.",
      "Pagkatapos bumaba ang apoy sa Bundok Carmelo, tumakas si Elias kay Jezebel, umupo sa ilalim ng isang punong retama at nanalanging mamatay na sana (1 Hari 19:1-4). Hindi siya pinagalitan ng Diyos. Hinipo siya ng isang anghel at sinabing, \"Bumangon ka at kumain, sapagkat napakahaba ng lalakbayin mo\" (t. 5-7), at saka pa lang nagsalita ang Diyos sa banayad na bulong. Nang bumalik ang mga apostol na masaya mula sa ministeryo, sabi ni Hesus, \"Sumama kayo sa Akin sa isang tahimik na lugar at magpahinga kayo\" (Marcos 6:31). At iniuutos ng Kawikaan 4:23, \"Higit sa lahat, ingatan mo ang iyong puso, sapagkat dito nagmumula ang lahat ng iyong ginagawa.\" Kasinlusog lang ng iyong ministeryo ang pusong pinagmumulan nito."
    ),
    insight: [
      t(
        "Elijah's crash came right after his greatest victory. Many believers assume burnout comes from failure, but it often comes after success: the big event, the busy season, the revival. Adrenaline hides the emptiness until it is gone. A wise worker watches his heart most carefully not when things fall apart, but when everything seems to be going well.",
        "Bumagsak si Elias pagkatapos mismo ng pinakamalaki niyang tagumpay. Akala ng marami, ang pagkapagod ay galing sa kabiguan, pero madalas ay dumarating ito pagkatapos ng tagumpay: ang malaking event, ang abalang panahon, ang pagbuhos ng pagpapala. Itinatago ng adrenaline ang pagkaubos hanggang mawala ito. Ang matalinong manggagawa ay pinakamaingat sa kanyang puso hindi kapag gumuguho ang lahat, kundi kapag mukhang maayos ang lahat."
      ),
      t(
        "Notice also how God treated His tired prophet: sleep, food, another nap, more food, and only then a conversation. Sometimes the most spiritual thing you can do is go to bed. Many church workers feel guilty resting, as if rest were unspiritual. But the same God who commands work also commands Sabbath. Neglecting rest is not devotion; it is often pride pretending to be zeal.",
        "Pansinin din kung paano tinrato ng Diyos ang Kanyang pagod na propeta: tulog, pagkain, idlip ulit, pagkain ulit, at saka pa lang ang pag-uusap. Minsan, ang pinakaespirituwal na magagawa mo ay matulog. Maraming manggagawa ng simbahan ang nakokonsensya kapag nagpapahinga, na para bang hindi espirituwal ang pahinga. Pero ang Diyos na nag-uutos ng paggawa ay nag-uutos din ng Sabbath. Ang pagpapabaya sa pahinga ay hindi debosyon; madalas ito ay kayabangang nagpapanggap na sigasig."
      ),
    ],
    life: [
      t(
        "Kuya Jun served as cell leader, sound tech and driver for his fellowship in Qatar, on top of twelve-hour shifts. He preached on prayer but had not prayed alone in weeks. One night he snapped at his wife on video call and realized he was empty. His pastor told him, \"Brother, a phone that serves everyone but is never charged will die.\" He stepped back from two roles, started a daily quiet time again, and his joy came back.",
        "Si Kuya Jun ay cell leader, sound tech at drayber ng fellowship nila sa Qatar, bukod pa sa labindalawang oras na duty. Nangangaral siya tungkol sa panalangin pero ilang linggo na siyang hindi nananalangin nang mag-isa. Isang gabi, nasigawan niya ang asawa niya sa video call at doon niya napagtantong ubos na siya. Sabi ng pastor niya, \"Brother, ang cellphone na naglilingkod sa lahat pero hindi kailanman naka-charge ay mamamatay.\" Binitawan niya ang dalawang tungkulin, bumalik sa araw-araw na quiet time, at bumalik ang kanyang kagalakan."
      ),
      t(
        "Guarding your heart also means guarding your home. Many workers give their best energy to the church and their leftovers to their spouse and children. It also means having at least one honest friend who can ask, \"How is your soul?\" Hidden sin, bitterness toward leaders and secret discouragement grow best in isolation.",
        "Ang pag-iingat sa puso ay pag-iingat din sa tahanan. Maraming manggagawa ang nagbibigay ng pinakamabuting lakas sa iglesia at ng tira-tira sa asawa at mga anak. Kasama rin dito ang pagkakaroon ng kahit isang tapat na kaibigang kayang magtanong, \"Kumusta ang kaluluwa mo?\" Ang tagong kasalanan, ang hinanakit sa mga lider at ang lihim na panghihina ng loob ay pinakamabilis lumago sa pag-iisa."
      ),
    ],
    twist: t(
      "We think God is most pleased when we are busiest for Him. But Jesus once pulled His disciples away from a crowd of needy people to rest, and the needs were still there. The Savior of the world was not anxious about the unfinished work. Rest is a confession of faith: it says, \"God runs the world, not me.\" A worker who cannot stop may be trusting his own strength more than he admits.",
      "Akala natin, pinakanalulugod ang Diyos kapag pinakaabala tayo para sa Kanya. Pero minsan, inilayo ni Hesus ang mga alagad Niya sa maraming nangangailangang tao para magpahinga, at naroon pa rin ang mga pangangailangan. Hindi nabalisa ang Tagapagligtas ng mundo sa gawaing hindi pa tapos. Ang pahinga ay pagpapahayag ng pananampalataya: sinasabi nito, \"Ang Diyos ang nagpapatakbo ng mundo, hindi ako.\" Ang manggagawang hindi kayang huminto ay baka mas nagtitiwala sa sariling lakas kaysa sa inaamin niya."
    ),
    confirm: [
      t("Exodus 18:17-23: Jethro tells Moses, \"What you are doing is not good; you will wear yourself out.\"", "Exodo 18:17-23: sabi ni Jetro kay Moises, \"Hindi mabuti ang ginagawa mo; mapapagod ka nang husto.\""),
      t("Psalm 23:2-3: He makes me lie down in green pastures and restores my soul.", "Awit 23:2-3: pinahihiga Niya ako sa luntiang pastulan at pinanunumbalik ang aking kaluluwa."),
      t("Matthew 11:28-30: come to Me, all who are weary, and I will give you rest.", "Mateo 11:28-30: lumapit kayo sa Akin, kayong lahat na pagod, at bibigyan Ko kayo ng kapahingahan."),
      t("Acts 20:28: keep watch over yourselves first, then over all the flock.", "Gawa 20:28: bantayan muna ninyo ang inyong sarili, at pagkatapos ang buong kawan."),
    ],
    heart: [
      t(
        "Repent of the belief that everything depends on you. Receive rest as a gift, not as a reward you must earn after the work is done.",
        "Pagsisihan ang paniniwalang nakasalalay sa iyo ang lahat. Tanggapin ang pahinga bilang regalo, hindi bilang gantimpalang kailangan mong pagtrabahuhan."
      ),
      t(
        "Feed your own soul before you feed others. Let your devotion be for loving God, not only for preparing lessons.",
        "Pakainin muna ang sarili mong kaluluwa bago mo pakainin ang iba. Hayaang ang iyong debosyon ay para sa pagmamahal sa Diyos, hindi lang para sa paghahanda ng aralin."
      ),
    ],
    questions: [
      t("What are your warning signs of running on empty: irritability, numbness, hidden habits, or prayerlessness?", "Ano ang mga palatandaan na nauubos ka na: pagiging iritable, pamamanhid, tagong bisyo, o kawalan ng panalangin?"),
      t("When did you last rest without guilt?", "Kailan ka huling nagpahinga nang hindi nakokonsensya?"),
      t("Who gets your leftovers: God, your family, or your own soul?", "Sino ang nakakatanggap ng tira-tira mo: ang Diyos, ang pamilya mo, o ang sarili mong kaluluwa?"),
      t("Who knows the real state of your heart right now?", "Sino ang nakakaalam ng tunay na kalagayan ng puso mo ngayon?"),
    ],
    actions: [
      t("Block out one real Sabbath this week: no ministry tasks, just rest, worship, family and a long meal.", "Maglaan ng isang tunay na Sabbath ngayong linggo: walang gawain sa ministeryo, puro pahinga, pagsamba, pamilya at mahabang kainan."),
      t("Have one honest conversation with a trusted friend or your pastor about how your heart is really doing.", "Magkaroon ng isang tapat na pag-uusap kasama ang pinagkakatiwalaang kaibigan o pastor tungkol sa tunay na kalagayan ng puso mo."),
      t("If you carry too many roles, list them and ask your leader which one you can hand to someone else.", "Kung masyadong marami ang tungkulin mo, ilista ang mga ito at itanong sa lider kung alin ang puwede mong ipasa sa iba."),
    ],
    prayer: t(
      "Gentle Father, You saw Elijah under the bush and You see me too. I am tired in ways I have not admitted. Forgive me for running on my own strength and calling it zeal. Feed me, rest me, and speak to me in Your quiet whisper. Guard my heart from bitterness, hidden sin and pride. Restore my joy, and teach me to serve from fullness, not from emptiness. In Jesus' name, Amen.",
      "Mahinahong Ama, nakita Mo si Elias sa ilalim ng puno at nakikita Mo rin ako. Pagod ako sa mga paraang hindi ko pa inaamin. Patawarin Mo ako sa pagtakbo sa sarili kong lakas at pagtawag dito na sigasig. Pakainin Mo ako, pagpahingahin Mo ako, at kausapin Mo ako sa Iyong tahimik na bulong. Ingatan Mo ang aking puso sa hinanakit, tagong kasalanan at kayabangan. Ibalik Mo ang aking kagalakan, at turuan Mo akong maglingkod mula sa kapuspusan, hindi mula sa pagkaubos. Sa pangalan ni Hesus, Amen."
    ),
  },

  "the-heart-of-a-deacon": {
    revelation: t(
      "In God's eyes, arranging food for widows is as spiritual as preaching, because both are the hands of Christ serving His people.",
      "Sa paningin ng Diyos, ang pag-aayos ng pagkain para sa mga balo ay kasing-espirituwal ng pangangaral, dahil pareho itong mga kamay ni Cristo na naglilingkod sa Kanyang bayan."
    ),
    mainTruth: t(
      "When Greek-speaking widows were being overlooked in the daily food distribution, the apostles asked the church to choose seven men \"full of the Spirit and wisdom\" to handle it, so they could give themselves \"to prayer and the ministry of the word\" (Acts 6:1-4). Paul later listed what servants (deacons) must be: worthy of respect, sincere, not given to much wine or greedy, keeping \"hold of the deep truths of the faith with a clear conscience,\" tested first, and faithful at home (1 Timothy 3:8-13). He commended Phoebe, \"a deacon of the church in Cenchreae,\" who had been \"the benefactor of many people, including me\" (Romans 16:1-2). Practical service, done with Spirit-filled character, is Kingdom work.",
      "Nang napapabayaan ang mga balong nagsasalita ng Griego sa araw-araw na pamamahagi ng pagkain, hiniling ng mga apostol sa iglesia na pumili ng pitong lalaking \"puspos ng Espiritu at karunungan\" para mangasiwa rito, upang maitalaga nila ang kanilang sarili \"sa panalangin at sa ministeryo ng Salita\" (Gawa 6:1-4). Kalaunan, inilista ni Pablo kung ano dapat ang mga lingkod (diyakono): kagalang-galang, tapat, hindi lasenggo o sakim, nanghahawak sa \"malalim na katotohanan ng pananampalataya nang may malinis na budhi,\" sinubok muna, at tapat sa tahanan (1 Timoteo 3:8-13). Pinuri niya si Febe, \"lingkod ng iglesia sa Cencrea,\" na naging \"katulong ng marami, pati na rin ako\" (Roma 16:1-2). Ang praktikal na paglilingkod, na ginagawa nang may karakter na puspos ng Espiritu, ay gawain ng Kaharian."
    ),
    insight: [
      t(
        "Notice the qualification for men who would serve tables: \"full of the Spirit and wisdom.\" The apostles did not say, \"Just find anyone free on Saturday.\" Handling food, money and complaints requires the Holy Spirit as much as preaching does, because such work touches people's dignity, fairness and trust. Some of the deepest wounds in churches come not from bad sermons but from unfair handling of practical things.",
        "Pansinin ang kwalipikasyon ng mga maglilingkod sa mesa: \"puspos ng Espiritu at karunungan.\" Hindi sinabi ng mga apostol, \"Maghanap lang ng kahit sinong bakante tuwing Sabado.\" Ang paghawak ng pagkain, pera at reklamo ay nangangailangan ng Banal na Espiritu gaya ng pangangaral, dahil humihipo ito sa dignidad, katarungan at tiwala ng tao. Ang ilan sa pinakamalalim na sugat sa iglesia ay hindi galing sa masamang sermon kundi sa hindi patas na paghawak ng mga praktikal na bagay."
      ),
      t(
        "We also overlook that Paul's list is mostly about character, not skill. \"Tested first,\" \"faithful at home,\" \"not greedy.\" A deacon's heart is proven long before it is appointed. And look what came from those seven: Stephen became the first martyr, and Philip became an evangelist who brought the gospel to Samaria. Faithfulness in serving tables became the training ground for greater things.",
        "Nakakaligtaan din natin na ang listahan ni Pablo ay halos tungkol sa karakter, hindi sa kasanayan. \"Sinubok muna,\" \"tapat sa tahanan,\" \"hindi sakim.\" Napapatunayan ang puso ng diyakono bago pa siya italaga. At tingnan kung ano ang lumabas sa pitong iyon: si Esteban ang naging unang martir, at si Felipe ay naging ebanghelista na nagdala ng ebanghelyo sa Samaria. Ang katapatan sa paglilingkod sa mesa ang naging pagsasanay para sa mas malalaking bagay."
      ),
    ],
    life: [
      t(
        "In one church, the pastor kept getting complaints that some families always received relief goods while others were forgotten. He could have spent all week sorting rice bags. Instead, he asked a quiet, trusted couple, known for honesty in their sari-sari store, to organize a list and system. The complaints stopped, the pastor returned to prayer and preaching, and the church grew. That couple never preached once, yet the whole church was strengthened through them.",
        "Sa isang iglesia, palaging may reklamo sa pastor na may mga pamilyang laging nabibigyan ng relief goods habang ang iba ay nakakalimutan. Puwede sana siyang gumugol ng buong linggo sa pag-aayos ng mga sako ng bigas. Sa halip, hiniling niya sa isang tahimik at mapagkakatiwalaang mag-asawa, kilala sa katapatan sa kanilang sari-sari store, na mag-ayos ng listahan at sistema. Nawala ang reklamo, nakabalik ang pastor sa panalangin at pangangaral, at lumago ang iglesia. Hindi kailanman nangaral ang mag-asawang iyon, pero napalakas ang buong iglesia sa pamamagitan nila."
      ),
      t(
        "Phoebe likely carried Paul's letter to Rome, a journey of great trust. Today a \"Phoebe\" might be the sister who handles the fellowship's funds with perfect records, or the brother who drives members to the embassy. Titles differ among churches, but the heart is the same: reliable, generous, unseen service that frees others to do their part.",
        "Malamang si Febe ang nagdala ng sulat ni Pablo sa Roma, isang paglalakbay na nangangailangan ng malaking tiwala. Ngayon, ang isang \"Febe\" ay maaaring ang sister na humahawak ng pondo ng fellowship nang may maayos na rekord, o ang brother na naghahatid sa mga miyembro sa embahada. Iba-iba ang titulo sa bawat iglesia, pero iisa ang puso: maaasahan, mapagbigay at tagong paglilingkod na nagpapalaya sa iba na gawin ang kanilang bahagi."
      ),
    ],
    twist: t(
      "We often rank ministries: the pulpit at the top, the kitchen at the bottom. But the very word Paul uses for deacon, diakonos, is the word Jesus used for Himself: \"The Son of Man did not come to be served, but to serve\" (Mark 10:45). Every deacon is wearing Jesus' own job title. The person carrying the trays may be standing closer to the heart of Christ than the person holding the microphone.",
      "Madalas nating niraranggo ang mga ministeryo: ang pulpito sa itaas, ang kusina sa ibaba. Pero ang mismong salitang ginamit ni Pablo para sa diyakono, diakonos, ay ang salitang ginamit ni Hesus para sa Kanyang sarili: \"Ang Anak ng Tao ay hindi naparito upang paglingkuran, kundi upang maglingkod\" (Marcos 10:45). Bawat diyakono ay suot ang mismong titulo ng trabaho ni Hesus. Ang taong may dalang mga tray ay maaaring mas malapit sa puso ni Cristo kaysa sa taong may hawak ng mikropono."
    ),
    confirm: [
      t("Acts 6:7: after the deacons served, the word spread and the disciples increased rapidly.", "Gawa 6:7: matapos maglingkod ang mga diyakono, lumaganap ang Salita at mabilis na dumami ang mga alagad."),
      t("Acts 8:5-8: Philip, a table servant, brings great joy to a Samaritan city.", "Gawa 8:5-8: si Felipe, isang lingkod sa mesa, ay nagdala ng malaking kagalakan sa isang lungsod sa Samaria."),
      t("Luke 16:10: whoever is faithful in little will be faithful in much.", "Lucas 16:10: ang tapat sa maliit ay magiging tapat din sa malaki."),
      t("Matthew 20:26-28: whoever wants to be great must be your servant.", "Mateo 20:26-28: ang sinumang gustong maging dakila ay dapat maging lingkod ninyo."),
    ],
    heart: [
      t(
        "Stop calling practical service \"just\" anything. Treat the chairs, the funds, the food and the follow-up as holy work done for a holy God.",
        "Itigil ang pagtawag sa praktikal na paglilingkod na \"ito lang.\" Ituring ang mga upuan, ang pondo, ang pagkain at ang follow-up bilang banal na gawain para sa banal na Diyos."
      ),
      t(
        "Let your character be tested before your role is enlarged. Be trustworthy at home and with money, and God will trust you with more.",
        "Hayaang masubok ang iyong karakter bago palawakin ang iyong tungkulin. Maging mapagkakatiwalaan sa tahanan at sa pera, at ipagkakatiwala sa iyo ng Diyos ang higit pa."
      ),
    ],
    questions: [
      t("What practical needs in your church or group are being overlooked like the widows in Acts 6?", "Anong mga praktikal na pangangailangan sa inyong iglesia o grupo ang napapabayaan gaya ng mga balo sa Gawa 6?"),
      t("Which deacon quality do you most need to grow in: honesty, self-control, generosity or faithfulness at home?", "Aling katangian ng diyakono ang pinakakailangan mong palaguin: katapatan, pagpipigil sa sarili, pagkabukas-palad o katapatan sa tahanan?"),
      t("Do you secretly see practical service as less spiritual than teaching?", "Lihim mo bang tinitingnan na mas mababa ang praktikal na paglilingkod kaysa sa pagtuturo?"),
      t("Whose ministry could be freed if you took one practical burden off their shoulders?", "Kaninong ministeryo ang mapapalaya kung aakuin mo ang isang praktikal na pasanin mula sa kanila?"),
    ],
    actions: [
      t("Identify one practical need in your church or group and take responsibility for it this month.", "Tukuyin ang isang praktikal na pangangailangan sa inyong iglesia o grupo at akuin ito ngayong buwan."),
      t("If you handle money or goods, set up clear records and ask a second person to check them.", "Kung humahawak ka ng pera o gamit, gumawa ng malinaw na rekord at hilingin sa ibang tao na suriin ito."),
      t("Ask your pastor, \"What practical task would free you to pray and teach more?\"", "Tanungin ang pastor, \"Anong praktikal na gawain ang magpapalaya sa inyo para mas makapanalangin at makapagturo?\""),
    ],
    prayer: t(
      "Lord Jesus, You came not to be served but to serve. Give me the heart of a deacon: honest, faithful, generous and full of Your Spirit. Forgive me for thinking some work is beneath me. Let my hands carry food, chairs, money and messages as if I were carrying them for You. Prove my character in small things, keep my home in order, and use my service to free others for Your Word. In Your name, Amen.",
      "Panginoong Hesus, naparito Ka hindi upang paglingkuran kundi upang maglingkod. Bigyan Mo ako ng puso ng diyakono: tapat, maaasahan, mapagbigay at puspos ng Iyong Espiritu. Patawarin Mo ako sa pag-iisip na may gawaing mababa para sa akin. Nawa'y dalhin ng aking mga kamay ang pagkain, upuan, pera at mensahe na parang dinadala ko ang mga ito para sa Iyo. Patunayan Mo ang aking karakter sa maliliit na bagay, ayusin Mo ang aking tahanan, at gamitin Mo ang aking paglilingkod para mapalaya ang iba para sa Iyong Salita. Sa Iyong pangalan, Amen."
    ),
  },

  "serving-children": {
    revelation: t(
      "Children are not the church of tomorrow waiting in the hallway; Jesus welcomed them today, and whoever welcomes them welcomes Him.",
      "Ang mga bata ay hindi iglesia ng bukas na naghihintay sa pasilyo; tinanggap sila ni Hesus ngayon, at ang sinumang tumatanggap sa kanila ay tumatanggap sa Kanya."
    ),
    mainTruth: t(
      "When the disciples rebuked parents for bringing children, Jesus \"was indignant\" and said, \"Let the little children come to me, and do not hinder them, for the kingdom of God belongs to such as these\" (Mark 10:14). He took them in His arms and blessed them (10:16). He warned that anyone who causes one of these little ones to stumble would be better off thrown into the sea (Matthew 18:6), and said that whoever welcomes a child in His name welcomes Him (18:5). Timothy's faith began because \"from infancy you have known the Holy Scriptures\" (2 Timothy 3:15). Children's ministry is not babysitting; it is planting the gospel in the most open soil there is.",
      "Nang sawayin ng mga alagad ang mga magulang na nagdala ng mga bata, \"nagalit\" si Hesus at sinabing, \"Hayaan ninyong lumapit sa Akin ang maliliit na bata at huwag ninyo silang hadlangan, sapagkat ang kaharian ng Diyos ay para sa mga tulad nila\" (Marcos 10:14). Kinalong Niya sila at binasbasan (t. 16). Nagbabala Siya na ang sinumang magiging dahilan ng pagkatisod ng isa sa maliliit na ito ay mas mabuti pang itapon sa dagat (Mateo 18:6), at sinabi Niyang ang sinumang tumanggap sa isang bata sa Kanyang pangalan ay tumatanggap sa Kanya (t. 5). Nagsimula ang pananampalataya ni Timoteo dahil \"mula pagkabata ay alam mo na ang Banal na Kasulatan\" (2 Timoteo 3:15). Ang ministeryo sa mga bata ay hindi pagbabantay lang; ito ay pagtatanim ng ebanghelyo sa pinakabukas na lupa."
    ),
    insight: [
      t(
        "Mark 10:14 is one of the only places where the Gospels say Jesus was indignant, and it was at His own disciples for pushing children away. We rarely think of ourselves as the disciples in that story, but every time children's ministry gets the leftover room, the untrained volunteer and no budget, we are saying what they said: \"The Master is too busy for these.\"",
        "Ang Marcos 10:14 ay isa sa iilang lugar kung saan sinasabi ng mga Ebanghelyo na nagalit si Hesus, at sa sarili pa Niyang mga alagad dahil itinataboy nila ang mga bata. Bihira nating isipin na tayo ang mga alagad sa kuwentong iyon, pero tuwing ang ministeryo sa mga bata ay napupunta sa natirang kuwarto, sa boluntaryong walang pagsasanay at walang budget, sinasabi natin ang sinabi nila: \"Masyadong abala ang Guro para sa mga ito.\""
      ),
      t(
        "Jesus also connects welcome with warning. The same chapter that says \"welcome a child\" says \"do not cause one to stumble.\" Serving children means loving them and protecting them: prepared lessons, patient discipline, two adults present, screened volunteers, and honoring parents. Safety rules are not a lack of trust; they are a form of love that Jesus takes very seriously.",
        "Pinag-uugnay din ni Hesus ang pagtanggap at ang babala. Ang parehong kabanata na nagsasabing \"tanggapin ang bata\" ay nagsasabing \"huwag maging dahilan ng pagkatisod niya.\" Ang paglilingkod sa mga bata ay pagmamahal at pagprotekta sa kanila: nakahandang aralin, matiyagang disiplina, dalawang adultong naroroon, mga boluntaryong nasuri, at paggalang sa mga magulang. Ang mga patakaran sa kaligtasan ay hindi kawalan ng tiwala; anyo ito ng pagmamahal na sineseryoso ni Hesus."
      ),
    ],
    life: [
      t(
        "Ask a room of mature Christians when they first believed, and many will say, \"When I was a child.\" One pastor in Batangas remembers a Sunday school teacher who gave him a candy for every memory verse. He forgot the candy long ago, but he never forgot John 3:16, or the way she knelt to look him in the eyes. That teacher never stood in a pulpit, but a pulpit stands today because of her.",
        "Tanungin ang isang silid ng matatandang Kristiyano kung kailan sila unang sumampalataya, at marami ang magsasabing, \"Noong bata pa ako.\" Naaalala ng isang pastor sa Batangas ang Sunday school teacher na nagbibigay sa kanya ng kendi sa bawat memory verse. Matagal na niyang nakalimutan ang kendi, pero hindi niya nakalimutan ang Juan 3:16, o ang paraan ng pagluhod ng guro para tumingin sa kanyang mga mata. Hindi kailanman tumayo sa pulpito ang gurong iyon, pero may pulpitong nakatayo ngayon dahil sa kanya."
      ),
      t(
        "Many OFW parents worry about children growing up far away, raised by lolos and lolas. A church worker who teaches those children faithfully, prays for them by name and sends parents a short update is becoming an answer to an OFW's tearful prayer. You may be the spiritual parent a child needs while the real parent works abroad.",
        "Maraming magulang na OFW ang nag-aalala sa mga anak nilang lumalaki sa malayo, inaalagaan ng lolo at lola. Ang manggagawang tapat na nagtuturo sa mga batang iyon, ipinapanalangin sila sa pangalan at nagpapadala ng maikling update sa magulang ay nagiging sagot sa lumuluhang panalangin ng isang OFW. Ikaw ang maaaring maging espirituwal na magulang na kailangan ng bata habang nagtatrabaho sa abroad ang tunay niyang magulang."
      ),
    ],
    twist: t(
      "We think we bring children to Jesus so they can become like us. But Jesus said the opposite: \"Unless you change and become like little children, you will never enter the kingdom\" (Matthew 18:3). Children's ministry is a two-way school. While you teach them about God, they teach you how to trust Him: simply, openly and without pretending. The teacher is often the one being discipled.",
      "Akala natin, dinadala natin ang mga bata kay Hesus para maging katulad natin sila. Pero kabaligtaran ang sinabi ni Hesus: \"Malibang magbago kayo at maging tulad ng maliliit na bata, hindi kayo makapapasok sa kaharian\" (Mateo 18:3). Ang ministeryo sa mga bata ay paaralang dalawa ang direksyon. Habang tinuturuan mo sila tungkol sa Diyos, tinuturuan ka nila kung paano magtiwala sa Kanya: payak, bukas at walang pagkukunwari. Madalas, ang guro ang dinidisipulo."
    ),
    confirm: [
      t("1 Samuel 3:1-10: the boy Samuel hears God's voice in the house of the Lord.", "1 Samuel 3:1-10: narinig ng batang si Samuel ang tinig ng Diyos sa bahay ng Panginoon."),
      t("Deuteronomy 6:6-7: impress God's words on your children as you sit, walk, lie down and rise.", "Deuteronomio 6:6-7: ituro nang masikap ang Salita ng Diyos sa iyong mga anak sa pag-upo, paglakad, paghiga at pagbangon."),
      t("2 Kings 5:2-3: a captive little girl points a great general to God's prophet.", "2 Hari 5:2-3: isang batang babaeng bihag ang nagturo sa isang dakilang heneral sa propeta ng Diyos."),
      t("Psalm 78:4: we will tell the next generation the praiseworthy deeds of the Lord.", "Awit 78:4: isasalaysay namin sa susunod na salinlahi ang kapuri-puring gawa ng Panginoon."),
    ],
    heart: [
      t(
        "Repent of seeing children as a distraction from \"real\" ministry. Let Jesus' indignation become your conviction and His arms become your example.",
        "Pagsisihan ang pagtingin sa mga bata bilang abala sa \"tunay\" na ministeryo. Hayaang ang galit ni Hesus ay maging iyong paninindigan at ang Kanyang mga bisig ay maging iyong halimbawa."
      ),
      t(
        "Carry children's safety as a sacred trust. Be the worker who follows every protective rule gladly, because you love them.",
        "Pasanin ang kaligtasan ng mga bata bilang banal na pagtitiwala. Maging manggagawang masayang sumusunod sa bawat patakarang pangproteksyon, dahil mahal mo sila."
      ),
    ],
    questions: [
      t("Who taught you about God when you were young, and have you ever thanked them?", "Sino ang nagturo sa iyo tungkol sa Diyos noong bata ka, at napasalamatan mo na ba siya?"),
      t("In what ways does your church unintentionally \"hinder\" children from coming to Jesus?", "Sa anong mga paraan hindi sinasadyang \"hinahadlangan\" ng inyong iglesia ang mga bata na lumapit kay Hesus?"),
      t("What safety practices protect the children in your church, and do you follow them every time?", "Anong mga kasanayang pangkaligtasan ang nagpoprotekta sa mga bata sa inyong iglesia, at sinusunod mo ba ito palagi?"),
      t("What could a child teach you about trusting God this week?", "Ano ang maituturo sa iyo ng isang bata tungkol sa pagtitiwala sa Diyos ngayong linggo?"),
    ],
    actions: [
      t("Help in children's ministry once this month, even just as an assistant, and prepare well.", "Tumulong sa ministeryo ng mga bata kahit isang beses ngayong buwan, kahit bilang katulong lang, at maghanda nang mabuti."),
      t("Pray for the children of your church by name, and for the parents working far away.", "Ipanalangin sa pangalan ang mga bata sa inyong iglesia, at ang mga magulang na nagtatrabaho sa malayo."),
      t("Ask your leader for the church's child safety guidelines and commit to follow them fully.", "Hingin sa lider ang child safety guidelines ng iglesia at mangakong susundin ito nang buo."),
    ],
    prayer: t(
      "Lord Jesus, You took little children in Your arms and blessed them. Forgive me for the times I treated them as a bother. Give me Your patience, Your joy and Your protective love for every child You place in front of me. Help me plant Your Word in young hearts so that, like Timothy, they will know You from childhood. And make me humble and trusting like a child before You. In Your name, Amen.",
      "Panginoong Hesus, kinalong Mo ang maliliit na bata at binasbasan sila. Patawarin Mo ako sa mga panahong itinuring ko silang abala. Bigyan Mo ako ng Iyong pagtitiyaga, kagalakan at mapag-ingat na pag-ibig para sa bawat batang inilalagay Mo sa harap ko. Tulungan Mo akong itanim ang Iyong Salita sa mga batang puso upang, gaya ni Timoteo, makilala Ka nila mula pagkabata. At gawin Mo akong mapagpakumbaba at mapagtiwala gaya ng bata sa harap Mo. Sa Iyong pangalan, Amen."
    ),
  },

  "serving-young-people": {
    revelation: t(
      "Young people do not need a church that entertains them or looks down on them; they need adults who believe God can use them now and show them how.",
      "Hindi kailangan ng kabataan ang iglesiang nagpapasaya lang sa kanila o minamaliit sila; kailangan nila ng mga nakatatandang naniniwalang kaya silang gamitin ng Diyos ngayon at nagpapakita sa kanila kung paano."
    ),
    mainTruth: t(
      "\"Remember your Creator in the days of your youth, before the days of trouble come\" (Ecclesiastes 12:1). Youth is the best season to give your life to God, not the season to waste it. Paul told young Timothy, \"Don't let anyone look down on you because you are young, but set an example for the believers in speech, in conduct, in love, in faith and in purity\" (1 Timothy 4:12). And he told Titus to \"encourage the young men to be self-controlled,\" while Titus himself set the example \"by doing what is good\" with integrity and sound speech (Titus 2:6-8). God's plan for youth is not delay but direction, and that direction is passed on through example.",
      "\"Alalahanin mo ang iyong Manlilikha sa mga araw ng iyong kabataan, bago dumating ang mga araw ng kaguluhan\" (Eclesiastes 12:1). Ang kabataan ang pinakamagandang panahon para ialay ang buhay sa Diyos, hindi panahon para sayangin ito. Sinabi ni Pablo sa batang si Timoteo, \"Huwag mong hayaang maliitin ka ng sinuman dahil bata ka, kundi maging halimbawa ka sa mga mananampalataya sa pananalita, sa pamumuhay, sa pag-ibig, sa pananampalataya at sa kalinisan\" (1 Timoteo 4:12). At sinabi niya kay Tito na \"himukin ang mga kabataang lalaki na maging mapagpigil sa sarili,\" habang si Tito mismo ay nagiging halimbawa \"sa paggawa ng mabuti\" nang may integridad at tamang pananalita (Tito 2:6-8). Ang plano ng Diyos para sa kabataan ay hindi pagpapaliban kundi direksyon, at naipapasa ang direksyong iyon sa pamamagitan ng halimbawa."
    ),
    insight: [
      t(
        "Notice that Paul did not tell the older believers, \"Don't look down on Timothy.\" He told Timothy, \"Don't let anyone look down on you, by being an example.\" Young people earn respect not by demanding it, but by living it. Youth workers help most when they call young people up to that standard instead of lowering it to keep them entertained.",
        "Pansinin na hindi sinabi ni Pablo sa mga nakatatandang mananampalataya, \"Huwag ninyong maliitin si Timoteo.\" Sinabi niya kay Timoteo, \"Huwag mong hayaang maliitin ka ng sinuman, sa pamamagitan ng pagiging halimbawa.\" Nakakamit ng kabataan ang paggalang hindi sa paghingi nito, kundi sa pamumuhay nito. Pinakamalaki ang tulong ng youth workers kapag tinatawag nila ang kabataan pataas sa pamantayang iyon sa halip na ibaba ito para lang manatili silang aliw."
      ),
      t(
        "The other side is just as important: Titus was told to show integrity himself. Young people can smell hypocrisy from far away. They will forget your youth camp program, but they will remember whether you kept your word, how you spoke about your spouse, and whether your faith was real when life was hard. Your life is the curriculum.",
        "Kasinghalaga ang kabilang panig: sinabihan si Tito na siya mismo ay magpakita ng integridad. Naaamoy ng kabataan ang pagkukunwari mula sa malayo. Makakalimutan nila ang programa ng youth camp mo, pero maaalala nila kung tinupad mo ang salita mo, kung paano ka nagsalita tungkol sa asawa mo, at kung totoo ang pananampalataya mo noong mahirap ang buhay. Ang buhay mo ang kurikulum."
      ),
    ],
    life: [
      t(
        "A seventeen-year-old named Paolo kept attending youth service but stayed at the back with his phone. One youth leader, instead of scolding him, asked him to help run the projector. Months later, Paolo was leading the media team and bringing his barkada. \"No one ever trusted me with anything before,\" he said. Giving young people real responsibility often reaches them faster than another lecture.",
        "Isang labimpitong taong gulang na si Paolo ang patuloy na dumadalo sa youth service pero nananatili sa likod na nakatutok sa cellphone. Isang youth leader, sa halip na pagalitan siya, ang humiling na tumulong siya sa projector. Pagkalipas ng ilang buwan, si Paolo na ang namumuno sa media team at dinadala na ang kanyang barkada. \"Ngayon lang may nagtiwala sa akin,\" sabi niya. Ang pagbibigay ng tunay na responsibilidad sa kabataan ay madalas mas mabilis umabot sa kanila kaysa sa panibagong sermon."
      ),
      t(
        "Many Filipino young people today carry heavy pressures: family expectations to finish school and work abroad, loneliness when parents are OFWs, and constant comparison online. A youth worker who simply listens over merienda, asks honest questions, and stays available when they mess up becomes a safe place where the gospel can be heard.",
        "Maraming kabataang Pilipino ngayon ang may mabigat na pasanin: ang inaasahan ng pamilya na makatapos at mag-abroad, ang kalungkutan kapag OFW ang magulang, at ang walang-tigil na paghahambing online. Ang youth worker na nakikinig lang habang nagmemerienda, nagtatanong nang tapat, at nananatiling available kapag nagkakamali sila ay nagiging ligtas na lugar kung saan maririnig ang ebanghelyo."
      ),
    ],
    twist: t(
      "We often treat youth as preparation for \"real\" life and ministry later. But in Scripture, God repeatedly chose the young for major assignments: Joseph, Samuel, David, Jeremiah, Daniel, Mary, Timothy. Youth is not the waiting room of the Kingdom; it is often the front line. The question is not \"When will they be ready?\" but \"Who will walk beside them now?\"",
      "Madalas nating tinatrato ang kabataan bilang paghahanda para sa \"tunay\" na buhay at ministeryo sa hinaharap. Pero sa Kasulatan, paulit-ulit na pinili ng Diyos ang mga bata pa para sa malalaking gawain: si Jose, si Samuel, si David, si Jeremias, si Daniel, si Maria, si Timoteo. Ang kabataan ay hindi waiting room ng Kaharian; madalas ito ang unahan ng laban. Ang tanong ay hindi \"Kailan sila magiging handa?\" kundi \"Sino ang lalakad kasama nila ngayon?\""
    ),
    confirm: [
      t("1 Samuel 17:33-37: Saul says David is only a boy; David has already learned to trust God.", "1 Samuel 17:33-37: sabi ni Saul bata pa lang si David; pero natutunan na ni David ang magtiwala sa Diyos."),
      t("Daniel 1:8: a young exile resolves not to defile himself in a foreign land.", "Daniel 1:8: isang batang bihag ang nagpasyang hindi dudungisan ang sarili sa banyagang lupain."),
      t("Psalm 119:9: a young person keeps his way pure by living according to God's word.", "Awit 119:9: napananatiling malinis ng kabataan ang kanyang landas sa pamumuhay ayon sa Salita ng Diyos."),
      t("2 Timothy 2:2: what you heard from me, entrust to faithful people who will teach others.", "2 Timoteo 2:2: ang narinig mo sa akin, ipagkatiwala mo sa mga tapat na tao na magtuturo rin sa iba."),
    ],
    heart: [
      t(
        "Repent of looking down on young people or giving up on them. See them as God sees them: called, gifted and needed today.",
        "Pagsisihan ang pagmamaliit o pagsuko sa kabataan. Tingnan sila gaya ng pagtingin ng Diyos: tinawag, may kaloob at kailangan ngayon."
      ),
      t(
        "Let your own life become a message worth copying. Ask God for consistency, so that what young people see in you matches what they hear from you.",
        "Hayaang ang sarili mong buhay ay maging mensaheng karapat-dapat tularan. Hilingin sa Diyos ang pagkakapare-pareho, para tumugma ang nakikita ng kabataan sa iyo sa naririnig nila mula sa iyo."
      ),
    ],
    questions: [
      t("Who walked beside you when you were young, and what did they do that made a difference?", "Sino ang lumakad kasama mo noong bata ka pa, at ano ang ginawa nila na nagkaroon ng pagbabago?"),
      t("Do the young people in your church have real responsibilities, or only activities?", "May tunay bang responsibilidad ang kabataan sa inyong iglesia, o puro aktibidad lang?"),
      t("If a teenager followed you around for a week, what would they learn about following Jesus?", "Kung sinundan ka ng isang teenager sa loob ng isang linggo, ano ang matututunan niya tungkol sa pagsunod kay Hesus?"),
      t("Which young person is God prompting you to encourage, mentor or simply listen to?", "Sinong kabataan ang inuudyok ng Diyos na palakasin mo ang loob, gabayan, o pakinggan lang?"),
    ],
    actions: [
      t("Invite one young person for merienda this week and ask how they are really doing.", "Imbitahin ang isang kabataan para magmerienda ngayong linggo at itanong kung kumusta talaga siya."),
      t("Give one young person a real ministry task and coach them through it.", "Bigyan ang isang kabataan ng tunay na gawain sa ministeryo at gabayan siya rito."),
      t("Pray daily this week for three young people by name, including any children of OFWs in your church.", "Ipanalangin araw-araw ngayong linggo ang tatlong kabataan sa pangalan, kasama ang mga anak ng OFW sa inyong iglesia."),
    ],
    prayer: t(
      "Father, You call young people to remember You and to be examples in speech, life, love, faith and purity. Raise up a generation in our church that loves You boldly. Forgive me for the times I looked down on them or gave up on them. Make my life consistent, so that they can follow me as I follow Christ. Give me patience to listen, wisdom to guide, and faith to trust them with real work in Your Kingdom. In Jesus' name, Amen.",
      "Ama, tinatawag Mo ang kabataan na alalahanin Ka at maging halimbawa sa pananalita, pamumuhay, pag-ibig, pananampalataya at kalinisan. Magbangon Ka ng isang henerasyon sa aming iglesia na buong tapang na nagmamahal sa Iyo. Patawarin Mo ako sa mga panahong minaliit ko sila o sinukuan. Gawin Mong pare-pareho ang aking buhay, para masundan nila ako habang sinusundan ko si Cristo. Bigyan Mo ako ng pagtitiyagang makinig, karunungang gumabay, at pananampalatayang ipagkatiwala sa kanila ang tunay na gawain sa Iyong Kaharian. Sa pangalan ni Hesus, Amen."
    ),
  },

  "welcoming-every-guest": {
    revelation: t(
      "The way you welcome the stranger at the door is the way the gospel first looks to them: either like Christ's open arms, or like a closed circle.",
      "Ang paraan ng pagtanggap mo sa estranghero sa pinto ang unang itsura ng ebanghelyo sa kanila: maaaring parang bukas na bisig ni Cristo, o parang saradong bilog."
    ),
    mainTruth: t(
      "\"Keep on loving one another as brothers and sisters. Do not forget to show hospitality to strangers, for by so doing some people have shown hospitality to angels without knowing it\" (Hebrews 13:1-2). \"Accept one another, then, just as Christ accepted you, in order to bring praise to God\" (Romans 15:7). James warns sharply against giving the rich man a good seat and telling the poor man, \"Stand there\" or \"Sit on the floor by my feet,\" calling such favoritism sin (James 2:1-9). Christian welcome is measured by Christ's welcome of us: undeserved, warm and without partiality.",
      "\"Patuloy kayong magmahalan bilang magkakapatid. Huwag ninyong kalimutang tanggapin ang mga estranghero, sapagkat sa paggawa nito, may ilang nakapagpatuloy ng mga anghel nang hindi nila nalalaman\" (Hebreo 13:1-2). \"Kaya tanggapin ninyo ang isa't isa, gaya ng pagtanggap sa inyo ni Cristo, para sa ikaluluwalhati ng Diyos\" (Roma 15:7). Mahigpit na nagbabala si Santiago laban sa pagbibigay ng magandang upuan sa mayaman at pagsasabi sa mahirap, \"Diyan ka tumayo\" o \"Umupo ka sa sahig sa paanan ko,\" at tinawag niyang kasalanan ang ganitong pagtatangi (Santiago 2:1-9). Ang pagtanggap ng Kristiyano ay sinusukat sa pagtanggap sa atin ni Cristo: hindi natin karapat-dapat, mainit at walang pinapanigan."
    ),
    insight: [
      t(
        "Most churches believe they are friendly, and they are, to each other. Members laugh together after service while a first-time guest stands alone by the wall and leaves unnoticed. Warmth among insiders can feel like a wall to outsiders. Hospitality in the Bible (philoxenia) literally means \"love of strangers,\" not love of friends.",
        "Naniniwala ang karamihan sa mga iglesia na palakaibigan sila, at totoo naman, sa isa't isa. Nagtatawanan ang mga miyembro pagkatapos ng serbisyo habang ang bisitang unang beses dumalo ay nakatayong mag-isa sa tabi ng pader at umaalis nang hindi napapansin. Ang init sa pagitan ng mga magkakakilala ay maaaring maramdamang pader ng mga dayo. Ang pagpapatuloy sa Bibliya (philoxenia) ay literal na \"pag-ibig sa estranghero,\" hindi pag-ibig sa kaibigan."
      ),
      t(
        "James also exposes a quiet sin: we instinctively give honor to those who can benefit us. The well-dressed visitor gets a warm handshake; the smelly or awkward one gets a polite nod. But Romans 15:7 sets the standard: welcome others as Christ welcomed you. And when Christ welcomed you, you had nothing to offer Him.",
        "Inilalantad din ni Santiago ang isang tahimik na kasalanan: likas nating binibigyang-pugay ang mga taong may maibibigay sa atin. Ang bisitang maganda ang suot ay sinasalubong nang mainit na pakikipagkamay; ang mabaho o kakaiba ay tinatanguan lang nang magalang. Pero ang Roma 15:7 ang pamantayan: tanggapin ang iba gaya ng pagtanggap sa iyo ni Cristo. At nang tanggapin ka ni Cristo, wala kang maibibigay sa Kanya."
      ),
    ],
    life: [
      t(
        "A Filipina nurse newly arrived in Saudi Arabia found a fellowship through a friend's post. She was nervous and almost turned back at the door. An usher named Ate Mila smiled, asked her name, sat beside her, and after the service introduced her to three sisters from her own province. \"I came looking for a church,\" she later said, \"and I found a family in ten minutes.\" Today she is the one standing at the door.",
        "Isang bagong dating na Pinay nurse sa Saudi Arabia ang nakahanap ng fellowship sa post ng isang kaibigan. Kinakabahan siya at muntik nang umatras sa pinto. Isang usher na si Ate Mila ang ngumiti, nagtanong ng pangalan niya, tumabi sa kanya, at pagkatapos ng serbisyo ay ipinakilala siya sa tatlong sister mula sa sarili niyang probinsya. \"Naghanap ako ng simbahan,\" sabi niya kalaunan, \"at nakahanap ako ng pamilya sa loob ng sampung minuto.\" Ngayon, siya na ang nakatayo sa pinto."
      ),
      t(
        "We Filipinos are known for hospitality at home: \"Kain tayo!\" But sometimes we forget it at church. Welcome looks like learning names, helping people find seats, explaining what is happening, sitting with someone who is alone, and sending a short message during the week. Small acts, done consistently, tell guests, \"You belong here.\"",
        "Kilala tayong mga Pilipino sa pagiging mapagpatuloy sa bahay: \"Kain tayo!\" Pero minsan, nakakalimutan natin ito sa iglesia. Ganito ang itsura ng pagtanggap: pag-alam sa pangalan, pagtulong humanap ng upuan, pagpapaliwanag kung ano ang nangyayari, pagtabi sa taong mag-isa, at pagpapadala ng maikling mensahe sa loob ng linggo. Maliliit na gawa, na palaging ginagawa, ang nagsasabi sa bisita, \"Kabilang ka rito.\""
      ),
    ],
    twist: t(
      "We think hospitality is about how nice our building or snacks are. But Hebrews says the stranger might be an angel, and Jesus said the stranger might be Him (Matthew 25:35). The guest at the door is not an interruption to the service; the guest may be the very reason God sent you there that day. Sometimes the most important ministry on Sunday happens not on the stage, but at the entrance.",
      "Akala natin ang pagpapatuloy ay tungkol sa ganda ng ating gusali o meryenda. Pero sabi ng Hebreo, maaaring anghel ang estranghero, at sabi ni Hesus, maaaring Siya mismo ang estranghero (Mateo 25:35). Ang bisita sa pinto ay hindi abala sa serbisyo; maaaring siya ang mismong dahilan kung bakit ka ipinadala roon ng Diyos sa araw na iyon. Minsan, ang pinakamahalagang ministeryo tuwing Linggo ay hindi nangyayari sa entablado, kundi sa pasukan."
    ),
    confirm: [
      t("Genesis 18:1-8: Abraham runs to welcome three strangers and finds himself serving the Lord.", "Genesis 18:1-8: tumakbo si Abraham para salubungin ang tatlong estranghero at napaglingkuran pala niya ang Panginoon."),
      t("Luke 19:5-6: Jesus welcomes Himself to the house of Zacchaeus, the outsider.", "Lucas 19:5-6: inanyayahan ni Hesus ang sarili Niya sa bahay ni Zaqueo, ang itinakwil ng iba."),
      t("Acts 9:26-27: Barnabas welcomes Saul when the disciples were afraid of him.", "Gawa 9:26-27: tinanggap ni Bernabe si Saulo nang matakot sa kanya ang mga alagad."),
      t("1 Peter 4:9: offer hospitality to one another without grumbling.", "1 Pedro 4:9: magpatuluyan kayo sa isa't isa nang walang reklamo."),
    ],
    heart: [
      t(
        "Turn your eyes outward. Before you look for your friends on Sunday, look for the person who has no one.",
        "Ibaling ang iyong mga mata palabas. Bago mo hanapin ang mga kaibigan mo tuwing Linggo, hanapin muna ang taong walang kasama."
      ),
      t(
        "Repent of favoritism. Treat the poor, the awkward and the newcomer with the same honor you would give an important guest.",
        "Pagsisihan ang pagtatangi. Tratuhin ang mahirap, ang kakaiba at ang bagong dating nang may parehong paggalang na ibibigay mo sa mahalagang bisita."
      ),
    ],
    questions: [
      t("When was the last time you sat with someone you did not know at church?", "Kailan ka huling tumabi sa taong hindi mo kilala sa iglesia?"),
      t("Whom do you instinctively treat with more honor, and whom with less?", "Sino ang likas mong tinatrato nang mas may paggalang, at sino ang mas kaunti?"),
      t("Remember your first visit to a church: what made you feel welcome or unwelcome?", "Alalahanin ang una mong pagdalaw sa isang iglesia: ano ang nagparamdam sa iyo na tanggap ka o hindi?"),
      t("How does remembering how Christ welcomed you change the way you welcome others?", "Paano binabago ng pag-alala sa pagtanggap sa iyo ni Cristo ang paraan ng pagtanggap mo sa iba?"),
    ],
    actions: [
      t("This Sunday, greet at least two people you do not know, learn their names and introduce them to someone.", "Ngayong Linggo, batiin ang hindi bababa sa dalawang taong hindi mo kilala, alamin ang pangalan nila at ipakilala sila sa iba."),
      t("Send a short welcome message during the week to one visitor or newer member.", "Magpadala ng maikling mensahe ng pagbati sa loob ng linggo sa isang bisita o bagong miyembro."),
      t("Invite one person who seems alone to eat with you after the service.", "Anyayahan ang isang taong mukhang nag-iisa na kumain kasama mo pagkatapos ng serbisyo."),
    ],
    prayer: t(
      "Lord Jesus, You welcomed me when I was a stranger far from God, with nothing to offer You. Forgive me for the times I stayed in my comfortable circle and let someone leave unnoticed. Open my eyes to the lonely, the new, the poor and the awkward. Make my smile Your smile and my handshake Your open arms. Let every guest who meets me feel that they have come home. In Your name, Amen.",
      "Panginoong Hesus, tinanggap Mo ako noong ako ay estranghero na malayo sa Diyos, na walang maibibigay sa Iyo. Patawarin Mo ako sa mga panahong nanatili ako sa komportable kong grupo at hinayaang may umalis nang hindi napapansin. Buksan Mo ang aking mga mata sa nalulungkot, sa bago, sa mahirap at sa kakaiba. Gawin Mong Iyong ngiti ang aking ngiti at Iyong bukas na bisig ang aking pakikipagkamay. Nawa'y madama ng bawat bisitang makakatagpo ko na nakauwi na sila. Sa Iyong pangalan, Amen."
    ),
  },

  "serving-on-the-worship-team": {
    revelation: t(
      "On the worship team, you are not performing for the church; you are worshiping before God with the church following you into His presence.",
      "Sa worship team, hindi ka nagtatanghal para sa iglesia; sumasamba ka sa harap ng Diyos habang sumusunod ang iglesia sa iyo papasok sa Kanyang presensya."
    ),
    mainTruth: t(
      "David set apart musicians \"for the ministry of prophesying, accompanied by harps, lyres and cymbals,\" all of them \"trained and skilled in music for the Lord\" and serving \"under the supervision\" of their leaders (1 Chronicles 25:1-7). The psalmist calls, \"Sing joyfully to the Lord... play skillfully, and shout for joy\" (Psalm 33:1-3). And Paul says worship is meant to let \"the message of Christ dwell among you richly as you teach and admonish one another... singing to God with gratitude in your hearts\" (Colossians 3:16). Worship ministry joins skill, order and the Word, but it must flow from a grateful heart.",
      "Ibinukod ni David ang mga musikero \"para sa ministeryo ng pagpapahayag, sa saliw ng alpa, lira at pompiyang,\" silang lahat ay \"sinanay at mahusay sa musika para sa Panginoon\" at naglilingkod \"sa ilalim ng pangangasiwa\" ng kanilang mga pinuno (1 Cronica 25:1-7). Nananawagan ang mang-aawit, \"Umawit kayo nang may galak sa Panginoon... tumugtog nang mahusay, at sumigaw sa kagalakan\" (Awit 33:1-3). At sinabi ni Pablo na ang pagsamba ay para hayaang \"manahan nang sagana sa inyo ang salita ni Cristo habang nagtuturuan at nagpapaalalahanan kayo... umaawit sa Diyos nang may pasasalamat sa inyong puso\" (Colosas 3:16). Pinagsasama ng ministeryo ng pagsamba ang husay, kaayusan at ang Salita, pero kailangang dumaloy ito mula sa pusong nagpapasalamat."
    ),
    insight: [
      t(
        "Notice that the songs we sing are meant to teach. Colossians 3:16 puts singing next to teaching and admonishing. That means a worship team is also a teaching team. What we sing over and over shapes what people believe about God. A song with shallow or wrong words can quietly teach error, while a song full of Scripture plants truth deeper than many sermons.",
        "Pansinin na ang mga awit na kinakanta natin ay para magturo. Inilagay ng Colosas 3:16 ang pag-awit katabi ng pagtuturo at pagpapaalala. Ibig sabihin, ang worship team ay isa ring teaching team. Ang paulit-ulit nating inaawit ang humuhubog sa paniniwala ng tao tungkol sa Diyos. Ang awit na mababaw o mali ang mga salita ay tahimik na makapagtuturo ng mali, habang ang awit na puno ng Kasulatan ay nagtatanim ng katotohanan nang mas malalim kaysa sa maraming sermon."
      ),
      t(
        "The greatest danger on the worship team is rarely a wrong chord; it is a wrong heart. Comparison, jealousy over who gets to lead, sulking when not scheduled, or a life on Monday that contradicts the song on Sunday. Satan was once linked with heaven's beauty and fell through pride. Those who stand closest to the glory must guard their hearts most carefully against stealing it.",
        "Ang pinakamalaking panganib sa worship team ay bihirang isang maling chord; ito ay maling puso. Paghahambing, inggit kung sino ang mangunguna, pagtatampo kapag hindi naka-schedule, o buhay sa Lunes na sumasalungat sa awit sa Linggo. Ang pinakamalapit sa kaluwalhatian ang dapat pinakamaingat sa kanilang puso para hindi ito nakawin."
      ),
    ],
    life: [
      t(
        "A young guitarist in a Manila church was the most skilled player on the team, but he often arrived late and complained about song choices. One Sunday the worship leader asked him to sit out and simply worship from the congregation. At first he was offended. But that morning, with no instrument in his hands, he wept for the first time in years. \"I had been playing for God,\" he said, \"but I had stopped worshiping Him.\"",
        "Isang batang gitarista sa isang iglesia sa Maynila ang pinakamahusay tumugtog sa team, pero madalas siyang late at nagrereklamo sa mga napiling awit. Isang Linggo, hiniling ng worship leader na umupo muna siya at sumamba lang kasama ng kongregasyon. Noong una, nasaktan siya. Pero nang umagang iyon, walang instrumentong hawak, umiyak siya sa unang pagkakataon makalipas ang maraming taon. \"Tumutugtog ako para sa Diyos,\" sabi niya, \"pero tumigil na pala akong sumamba sa Kanya.\""
      ),
      t(
        "In many OFW fellowships, the worship team practices after long work shifts with borrowed instruments and a small speaker. That is beautiful in God's sight. Excellence is not about expensive equipment; it is about faithful practice, arriving early, knowing the songs well, praying together before you play, and living the words you sing.",
        "Sa maraming OFW fellowship, nag-eensayo ang worship team pagkatapos ng mahabang duty gamit ang hiram na instrumento at maliit na speaker. Maganda iyan sa paningin ng Diyos. Ang kahusayan ay hindi tungkol sa mamahaling gamit; ito ay tungkol sa tapat na pag-eensayo, maagang pagdating, pagkakilala nang mabuti sa mga awit, sama-samang pananalangin bago tumugtog, at pamumuhay sa mga salitang inaawit."
      ),
    ],
    twist: t(
      "We think the best worship team is the one the church notices most. But the best worship team is the one the church forgets, because their eyes have moved from the stage to the throne. Like John the Baptist, the worship leader's joy is to say, \"He must increase, I must decrease\" (John 3:30). When people leave saying \"What a great God\" instead of \"What a great band,\" the team has done its job.",
      "Akala natin ang pinakamahusay na worship team ay ang pinakapinapansin ng iglesia. Pero ang pinakamahusay na worship team ay ang nakakalimutan ng iglesia, dahil lumipat na ang kanilang mga mata mula sa entablado patungo sa trono. Gaya ni Juan Bautista, ang kagalakan ng worship leader ay sabihing, \"Kailangan Siyang maging dakila, at ako ay maging maliit\" (Juan 3:30). Kapag umalis ang mga tao na nagsasabing \"Napakadakila ng Diyos\" sa halip na \"Ang galing ng banda,\" nagawa ng team ang trabaho nito."
    ),
    confirm: [
      t("2 Chronicles 5:13-14: when the singers praised as one, the glory cloud filled the temple.", "2 Cronica 5:13-14: nang magpuri nang sabay-sabay ang mga mang-aawit, napuno ng ulap ng kaluwalhatian ang templo."),
      t("2 Chronicles 20:21-22: Jehoshaphat sent singers ahead of the army, and God gave victory.", "2 Cronica 20:21-22: pinauna ni Jehoshafat ang mga mang-aawit sa hukbo, at nagbigay ang Diyos ng tagumpay."),
      t("Amos 5:23-24: God rejects songs that are not matched by justice in daily life.", "Amos 5:23-24: tinatanggihan ng Diyos ang awit na hindi tinutumbasan ng katarungan sa araw-araw na buhay."),
      t("John 4:23-24: the Father seeks worshipers who worship in Spirit and in truth.", "Juan 4:23-24: hinahanap ng Ama ang mga sumasamba sa Espiritu at sa katotohanan."),
    ],
    heart: [
      t(
        "Be a worshiper first and a musician second. Spend more time in private worship than in public performance.",
        "Maging mananamba muna bago musikero. Gumugol ng mas maraming oras sa pribadong pagsamba kaysa sa pampublikong pagtatanghal."
      ),
      t(
        "Choose a humble, teachable spirit. Submit to your leaders, celebrate others' gifts, and let your Monday match your Sunday.",
        "Piliin ang mapagpakumbaba at madaling turuang espiritu. Magpasakop sa iyong mga lider, ipagdiwang ang kaloob ng iba, at hayaang tumugma ang iyong Lunes sa iyong Linggo."
      ),
    ],
    questions: [
      t("When you lead or play, whose attention are you most aware of: God's or people's?", "Kapag nangunguna o tumutugtog ka, kaninong atensyon ang pinakanararamdaman mo: ng Diyos o ng tao?"),
      t("Do the songs you sing match the life you live during the week?", "Tumutugma ba ang mga awit na inaawit mo sa buhay na ipinamumuhay mo sa buong linggo?"),
      t("How do you react when someone else is chosen to lead or play?", "Ano ang reaksyon mo kapag iba ang napiling mangunguna o tumugtog?"),
      t("Are you practicing with excellence as an offering, or only enough to get by?", "Nag-eensayo ka ba nang mahusay bilang handog, o sapat lang para makaraos?"),
    ],
    actions: [
      t("Practice your part faithfully this week and arrive early to pray with the team before you play.", "Ensayuhin nang tapat ang iyong bahagi ngayong linggo at dumating nang maaga para manalangin kasama ng team bago tumugtog."),
      t("Read the lyrics of this Sunday's songs as prayers in your quiet time, and check them against Scripture.", "Basahin ang mga liriko ng mga awit ngayong Linggo bilang panalangin sa iyong quiet time, at suriin ito ayon sa Kasulatan."),
      t("Pray for each team member by name, and encourage one of them personally.", "Ipanalangin ang bawat miyembro ng team sa pangalan, at palakasin ang loob ng isa sa kanila nang personal."),
    ],
    prayer: t(
      "Lord, You are worthy of every song and every skill. Forgive me for the times I wanted the applause that belongs to You. Make me a worshiper before I am a musician. Let the word of Christ dwell richly in me and in the songs we sing. Unite our team in humility and love, and let our lives match our lyrics. When we lead, draw every eye away from us and up to Your throne. In Jesus' name, Amen.",
      "Panginoon, karapat-dapat Ka sa bawat awit at bawat husay. Patawarin Mo ako sa mga panahong hinangad ko ang palakpak na para sa Iyo. Gawin Mo muna akong mananamba bago musikero. Nawa'y manahan nang sagana ang salita ni Cristo sa akin at sa mga awit na aming inaawit. Pagkaisahin Mo ang aming team sa kababaang-loob at pag-ibig, at nawa'y tumugma ang aming buhay sa aming mga liriko. Kapag nangunguna kami, ilayo Mo sa amin ang bawat mata at itaas sa Iyong trono. Sa pangalan ni Hesus, Amen."
    ),
  },

  "serving-behind-the-scenes": {
    revelation: t(
      "The Spirit who fills preachers also fills craftsmen; hidden service is not lesser ministry but indispensable ministry that God sees and honors.",
      "Ang Espiritung pumupuspos sa mga mangangaral ay pumupuspos din sa mga manggagawa ng kamay; ang tagong paglilingkod ay hindi mababang ministeryo kundi kailangang-kailangang ministeryo na nakikita at pinararangalan ng Diyos."
    ),
    mainTruth: t(
      "The first person in Scripture described as \"filled with the Spirit of God\" was not a prophet or a king but Bezalel, a craftsman given \"wisdom, understanding, knowledge and all kinds of skills\" to make artistic designs in gold, silver, bronze, stone and wood for the tabernacle (Exodus 31:1-6). Paul says the eye cannot tell the hand, \"I don't need you,\" and that \"those parts of the body that seem to be weaker are indispensable,\" with God giving \"greater honor to the parts that lacked it\" (1 Corinthians 12:21-25). Sound, media, cleaning, design, logistics, and building are gifts God gives so His people can gather and hear His Word.",
      "Ang unang taong inilarawan sa Kasulatan na \"puspos ng Espiritu ng Diyos\" ay hindi propeta o hari kundi si Bezalel, isang manggagawang binigyan ng \"karunungan, pang-unawa, kaalaman at lahat ng uri ng kasanayan\" para gumawa ng magagandang disenyo sa ginto, pilak, tanso, bato at kahoy para sa tabernakulo (Exodo 31:1-6). Sinabi ni Pablo na hindi masasabi ng mata sa kamay, \"Hindi kita kailangan,\" at ang \"mga bahagi ng katawan na mukhang mahina ay kailangang-kailangan,\" at ang Diyos ay nagbibigay ng \"higit na karangalan sa mga bahaging kulang nito\" (1 Corinto 12:21-25). Ang sound, media, paglilinis, disenyo, logistics at pagtatayo ay mga kaloob ng Diyos para makapagtipon ang Kanyang bayan at marinig ang Kanyang Salita."
    ),
    insight: [
      t(
        "Many church workers think the Spirit's power only shows up in preaching, prophecy and healing. Exodus 31 corrects that. God's Spirit was in the hands that carved wood and set stones. When you edit slides, fix cables or arrange chairs prayerfully, you are not outside the Spirit's work; you are in it.",
        "Maraming manggagawa ng simbahan ang nag-iisip na ang kapangyarihan ng Espiritu ay lumilitaw lang sa pangangaral, propesiya at pagpapagaling. Itinutuwid iyan ng Exodo 31. Nasa mga kamay na umuukit ng kahoy at naglalagay ng bato ang Espiritu ng Diyos. Kapag nag-eedit ka ng slides, nag-aayos ng kable o naglalagay ng upuan nang may panalangin, hindi ka labas sa gawain ng Espiritu; nasa loob ka nito."
      ),
      t(
        "The hidden risk of hidden service is quiet resentment. \"Nobody thanks me.\" \"They only notice when the mic fails.\" That feeling is real, but it can sour your heart. Paul's word is a comfort: God Himself gives honor to the parts that lack it. Your Father who sees in secret keeps better records than any church bulletin.",
        "Ang tagong panganib ng tagong paglilingkod ay ang tahimik na hinanakit. \"Walang nagpapasalamat sa akin.\" \"Napapansin lang nila kapag pumalya ang mic.\" Totoo ang pakiramdam na iyan, pero kaya nitong paasimin ang puso mo. Nakaaaliw ang salita ni Pablo: ang Diyos mismo ang nagbibigay ng karangalan sa mga bahaging kulang nito. Mas maayos ang talaan ng iyong Amang nakakakita sa lihim kaysa sa anumang bulletin ng iglesia."
      ),
    ],
    life: [
      t(
        "Imagine a Sunday where everything goes wrong behind the scenes: the mic crackles, the lyrics appear late, the aircon is off and the chairs are not ready. The preacher may be anointed, but people will struggle to hear and focus. Now imagine the opposite: clear sound, correct slides, a clean room. No one notices, and that is the point. The behind-the-scenes team removed every obstacle between the people and the Word.",
        "Isipin ang isang Linggo na pumalya ang lahat sa likod ng entablado: umuugong ang mic, huli lumabas ang lyrics, patay ang aircon at hindi pa ayos ang mga upuan. Maaaring pinahiran ang mangangaral, pero mahihirapan ang mga taong makarinig at makapagtuon. Ngayon, isipin ang kabaligtaran: malinaw ang tunog, tama ang slides, malinis ang silid. Walang nakapansin, at iyon mismo ang punto. Inalis ng team sa likod ang bawat hadlang sa pagitan ng mga tao at ng Salita."
      ),
      t(
        "Kuya Edgar, an electrician working in Dubai, runs the sound for his fellowship every Friday. He prays over each cable as he sets it up: \"Lord, let Your Word go clearly through this.\" One day a visitor said the message changed her life. Kuya Edgar smiled quietly at the mixer, because he knew he had a part in it, and that was enough.",
        "Si Kuya Edgar, isang electrician na nagtatrabaho sa Dubai, ang humahawak ng sound ng fellowship nila tuwing Biyernes. Ipinapanalangin niya ang bawat kable habang inaayos ito: \"Panginoon, nawa'y dumaan nang malinaw dito ang Iyong Salita.\" Isang araw, sinabi ng isang bisita na binago ng mensahe ang buhay niya. Tahimik na ngumiti si Kuya Edgar sa harap ng mixer, dahil alam niyang may bahagi siya roon, at sapat na iyon."
      ),
    ],
    twist: t(
      "We assume God's greatest honor goes to the most visible servants. But 1 Corinthians 12 reveals that God deliberately reverses that: He gives greater honor to the less visible parts. In heaven's ceremony, the sound tech may be called forward before the famous preacher. The Kingdom spotlight is pointed at places the world's spotlight never reaches.",
      "Inaakala nating ang pinakamataas na karangalan ng Diyos ay para sa pinakakita na lingkod. Pero inihahayag ng 1 Corinto 12 na sadyang binabaligtad iyon ng Diyos: nagbibigay Siya ng higit na karangalan sa mga bahaging hindi gaanong nakikita. Sa seremonya ng langit, maaaring unang tawagin ang sound tech bago ang tanyag na mangangaral. Nakatutok ang spotlight ng Kaharian sa mga lugar na hindi kailanman inaabot ng spotlight ng mundo."
    ),
    confirm: [
      t("Exodus 35:25-26: skilled women spun goat hair with willing hearts for God's house.", "Exodo 35:25-26: mga babaeng bihasa ang nag-ikid ng balahibo ng kambing nang may kusang puso para sa bahay ng Diyos."),
      t("Nehemiah 3:1-32: a long list of ordinary names, each repairing his own section of the wall.", "Nehemias 3:1-32: mahabang listahan ng karaniwang pangalan, bawat isa nag-aayos ng sariling bahagi ng pader."),
      t("Matthew 6:3-4: your Father who sees what is done in secret will reward you.", "Mateo 6:3-4: ang iyong Ama na nakakakita sa lihim ang magbibigay ng gantimpala sa iyo."),
      t("Romans 16:1-16: Paul honors a long list of mostly unknown co-workers by name.", "Roma 16:1-16: pinarangalan ni Pablo sa pangalan ang mahabang listahan ng halos hindi kilalang mga kamanggagawa."),
    ],
    heart: [
      t(
        "Exchange the need for applause for the joy of usefulness. Serve for the audience of One who never misses a single act.",
        "Ipagpalit ang pangangailangan sa palakpak sa kagalakan ng pagiging kapaki-pakinabang. Maglingkod para sa iisang Manonood na hindi nakakaligtaan ang kahit isang gawa."
      ),
      t(
        "Stay spiritually awake while you work. Worship with your hands even when you cannot sing with the congregation.",
        "Manatiling gising sa espiritu habang nagtatrabaho. Sumamba gamit ang iyong mga kamay kahit hindi ka makaawit kasama ng kongregasyon."
      ),
    ],
    questions: [
      t("Do you see your technical or practical skills as gifts from the Holy Spirit?", "Tinitingnan mo ba ang iyong teknikal o praktikal na kasanayan bilang kaloob ng Banal na Espiritu?"),
      t("Is there quiet resentment in your heart because your service goes unnoticed?", "May tahimik bang hinanakit sa puso mo dahil hindi napapansin ang iyong paglilingkod?"),
      t("How can you stay in worship while you are busy working during the service?", "Paano ka mananatili sa pagsamba habang abala ka sa trabaho sa loob ng serbisyo?"),
      t("Whose hidden work in your church have you never thanked?", "Kaninong tagong gawain sa inyong iglesia ang hindi mo pa kailanman napasalamatan?"),
    ],
    actions: [
      t("Before your next task, pray over your tools and ask God to use them to carry His Word clearly.", "Bago ang susunod mong gawain, ipanalangin ang iyong mga gamit at hilingin sa Diyos na gamitin ang mga ito para malinaw na maihatid ang Kanyang Salita."),
      t("Improve one detail of your behind-the-scenes work this week, such as checking slides early or testing equipment.", "Pagbutihin ang isang detalye ng iyong gawain sa likod ngayong linggo, gaya ng maagang pagsuri sa slides o pag-test ng kagamitan."),
      t("Write a thank-you note to one hidden servant in your church.", "Sumulat ng pasasalamat sa isang tagong lingkod sa inyong iglesia."),
    ],
    prayer: t(
      "Spirit of God, You filled Bezalel's hands with skill, and You give gifts to my hands too. Thank You that no part of the body is unimportant to You. Forgive me for any bitterness when I felt unseen. Let me serve with excellence and joy, knowing You see in secret. Use my work behind the scenes to clear the way for Your Word to reach hearts. Let my hands worship You. In Jesus' name, Amen.",
      "Espiritu ng Diyos, pinuspos Mo ng kasanayan ang mga kamay ni Bezalel, at binibigyan Mo rin ng kaloob ang aking mga kamay. Salamat dahil walang bahagi ng katawan na hindi mahalaga sa Iyo. Patawarin Mo ako sa anumang hinanakit noong pakiramdam ko'y hindi ako nakikita. Hayaan Mo akong maglingkod nang mahusay at may kagalakan, alam kong nakikita Mo ang nasa lihim. Gamitin Mo ang aking gawain sa likod ng entablado para mabuksan ang daan ng Iyong Salita patungo sa mga puso. Nawa'y sumamba sa Iyo ang aking mga kamay. Sa pangalan ni Hesus, Amen."
    ),
  },

  "intercessors-for-the-church": {
    revelation: t(
      "The battles of the church are won not only by those on the front line but by those on the hill with lifted hands; prayer is the hidden engine of every ministry.",
      "Ang mga laban ng iglesia ay napagtatagumpayan hindi lang ng mga nasa unahan kundi ng mga nasa burol na nakataas ang kamay; ang panalangin ang tagong makina ng bawat ministeryo."
    ),
    mainTruth: t(
      "While Joshua fought the Amalekites in the valley, Moses stood on the hill with the staff of God. \"As long as Moses held up his hands, the Israelites were winning,\" and when he grew tired, Aaron and Hur held his hands up until sunset (Exodus 17:8-13). Samuel told Israel, \"Far be it from me that I should sin against the Lord by failing to pray for you\" (1 Samuel 12:23). And God lamented, \"I looked for someone among them who would build up the wall and stand before me in the gap... but I found no one\" (Ezekiel 22:30). God has chosen to move through the prayers of His people, and He is still looking for those who will stand in the gap.",
      "Habang nakikipaglaban si Josue sa mga Amalekita sa lambak, nakatayo si Moises sa burol na hawak ang tungkod ng Diyos. \"Habang nakataas ang mga kamay ni Moises, nananalo ang mga Israelita,\" at nang mapagod siya, hinawakan nina Aaron at Hur ang kanyang mga kamay pataas hanggang paglubog ng araw (Exodo 17:8-13). Sinabi ni Samuel sa Israel, \"Malayong mangyari na magkasala ako sa Panginoon sa hindi pananalangin para sa inyo\" (1 Samuel 12:23). At nanaghoy ang Diyos, \"Naghanap Ako sa kanila ng taong magtatayo ng pader at tatayo sa puwang sa harap Ko... pero wala Akong natagpuan\" (Ezekiel 22:30). Pinili ng Diyos na kumilos sa pamamagitan ng mga panalangin ng Kanyang bayan, at hinahanap pa rin Niya ang mga tatayo sa puwang."
    ),
    insight: [
      t(
        "Samuel called prayerlessness a sin. We usually treat failing to pray for others as a small lapse, but Samuel saw it as abandoning his post. For a church worker, praying for the people you serve is not optional extra credit; it is part of the job description. A ministry that is busy but prayerless is like a soldier fighting without supply lines.",
        "Tinawag ni Samuel na kasalanan ang hindi pananalangin. Karaniwan, tinitingnan natin ang hindi pananalangin para sa iba bilang maliit na pagkukulang, pero nakita ito ni Samuel bilang pag-iwan sa kanyang puwesto. Para sa manggagawa ng simbahan, ang pananalangin para sa mga pinaglilingkuran ay hindi dagdag na puntos; bahagi ito ng trabaho. Ang ministeryong abala pero walang panalangin ay parang sundalong lumalaban nang walang suplay."
      ),
      t(
        "Notice also that even Moses got tired. The great intercessor needed Aaron and Hur. Intercession was never meant to be a solo ministry. Prayer teams work best when people hold each other up: sharing the load, covering one another, and keeping requests confidential so that people feel safe to share their deepest needs.",
        "Pansinin din na napagod pati si Moises. Kinailangan ng dakilang tagapamagitan sina Aaron at Hur. Ang pamamagitan ay hindi kailanman sinadyang maging ministeryo ng nag-iisa. Pinakamabuti ang prayer team kapag nagtutulungan ang mga tao: naghahati sa pasanin, nagtatakip sa isa't isa, at iniingatan ang mga prayer request para maging panatag ang mga tao na ibahagi ang pinakamalalim nilang pangangailangan."
      ),
    ],
    life: [
      t(
        "In one fellowship, a small group of older sisters met every Thursday night to pray over the church list by name: the pastor, the sick, the backsliders, the new believers, the families back home. They were never on stage. But when the church saw several members return to God and a long-sick brother recover, the pastor said, \"The real story of this church is happening on Thursday nights in Ate Nena's living room.\"",
        "Sa isang fellowship, isang maliit na grupo ng matatandang sister ang nagkikita tuwing Huwebes ng gabi para ipanalangin sa pangalan ang listahan ng iglesia: ang pastor, ang maysakit, ang mga tumalikod, ang mga bagong mananampalataya, ang mga pamilya sa Pilipinas. Hindi sila kailanman umakyat sa entablado. Pero nang makita ng iglesia ang pagbabalik sa Diyos ng ilang miyembro at ang paggaling ng isang matagal nang maysakit na brother, sabi ng pastor, \"Ang tunay na kuwento ng iglesiang ito ay nangyayari tuwing Huwebes ng gabi sa sala ni Ate Nena.\""
      ),
      t(
        "OFWs often say, \"I can't serve much; I only have my phone and my breaks.\" But you can stand on the hill from anywhere. A five-minute prayer for your pastor during lunch break, or praying through your fellowship's group chat requests before sleeping, is real ministry. Distance does not weaken prayer; God hears from Riyadh as clearly as from Manila.",
        "Madalas sabihin ng mga OFW, \"Hindi ako makapaglingkod nang malaki; cellphone at break time lang ang meron ako.\" Pero puwede kang tumayo sa burol mula saanman. Ang limang minutong panalangin para sa iyong pastor habang lunch break, o ang pananalangin sa mga request sa group chat ng fellowship bago matulog, ay tunay na ministeryo. Hindi pinahihina ng distansya ang panalangin; naririnig ng Diyos mula sa Riyadh nang kasinlinaw ng mula sa Maynila."
      ),
    ],
    twist: t(
      "We picture the victory in Exodus 17 as Joshua's victory, because he held the sword. But the text makes clear the battle was decided on the hill. In God's economy, the person kneeling unseen may be doing more for the church than the person preaching on stage. Heaven's history books will credit many victories to people whose names were never announced.",
      "Iniisip nating ang tagumpay sa Exodo 17 ay tagumpay ni Josue, dahil siya ang may hawak ng espada. Pero malinaw sa talata na sa burol napagpasyahan ang labanan. Sa pamamaraan ng Diyos, ang taong nakaluhod na hindi nakikita ay maaaring mas maraming nagagawa para sa iglesia kaysa sa taong nangangaral sa entablado. Itatala ng aklat ng kasaysayan ng langit ang maraming tagumpay sa mga taong hindi kailanman inanunsyo ang pangalan."
    ),
    confirm: [
      t("Genesis 18:22-33: Abraham stands before the Lord and pleads for Sodom.", "Genesis 18:22-33: tumayo si Abraham sa harap ng Panginoon at nakiusap para sa Sodoma."),
      t("Acts 12:5-12: the church prays earnestly, and Peter walks out of prison.", "Gawa 12:5-12: masigasig na nanalangin ang iglesia, at nakalabas si Pedro sa bilangguan."),
      t("Colossians 4:12: Epaphras is always wrestling in prayer for the church.", "Colosas 4:12: si Epafras ay laging nakikipagbuno sa panalangin para sa iglesia."),
      t("Romans 8:26-27, 34: the Spirit and the Son both intercede for us.", "Roma 8:26-27, 34: kapwa namamagitan para sa atin ang Espiritu at ang Anak."),
    ],
    heart: [
      t(
        "Repent of prayerlessness as Samuel would, not as a small slip but as a missed post. Take your place on the hill again.",
        "Pagsisihan ang hindi pananalangin gaya ng gagawin ni Samuel, hindi bilang maliit na pagkakamali kundi bilang naiwang puwesto. Bumalik sa iyong lugar sa burol."
      ),
      t(
        "Become an Aaron or Hur. Lift up the hands of your leaders and fellow intercessors when they grow tired.",
        "Maging isang Aaron o Hur. Itaas ang mga kamay ng iyong mga lider at kapwa tagapamagitan kapag napapagod sila."
      ),
    ],
    questions: [
      t("If your church's spiritual strength depended on your prayers this week, how strong would it be?", "Kung nakasalalay sa iyong mga panalangin ngayong linggo ang espirituwal na lakas ng inyong iglesia, gaano ito kalakas?"),
      t("Whom do you serve but rarely pray for by name?", "Sino ang pinaglilingkuran mo pero bihira mong ipanalangin sa pangalan?"),
      t("Is there a \"gap\" in your family, church or community where God is looking for someone to stand?", "May \"puwang\" ba sa inyong pamilya, iglesia o komunidad kung saan naghahanap ang Diyos ng tatayo?"),
      t("Can people trust you to keep their prayer requests confidential?", "Mapagkakatiwalaan ka ba ng mga tao na iingatan ang kanilang mga prayer request?"),
    ],
    actions: [
      t("Make a prayer list of your pastor, leaders, the sick and the lost in your church, and pray through it daily this week.", "Gumawa ng prayer list ng iyong pastor, mga lider, mga maysakit at mga hindi pa ligtas sa inyong iglesia, at ipanalangin ito araw-araw ngayong linggo."),
      t("Join or start a small prayer team that meets regularly, even online for fifteen minutes.", "Sumali o magsimula ng maliit na prayer team na regular na nagkikita, kahit online nang labinlimang minuto."),
      t("Send a message to your pastor this week: \"I prayed for you today. Is there anything specific I can pray for?\"", "Magpadala ng mensahe sa iyong pastor ngayong linggo: \"Ipinanalangin ko po kayo ngayon. May partikular po ba akong maipapanalangin?\""),
    ],
    prayer: t(
      "Father, You are looking for someone to stand in the gap, and I want to answer: here I am. Forgive me for the times I failed to pray for the people You gave me. Teach me to lift my hands for my pastor, my leaders, the sick, the weary and the lost. When I grow tired, send me an Aaron and a Hur, and make me one for others. Let our church be carried forward on the wings of faithful prayer. In Jesus' name, Amen.",
      "Ama, naghahanap Ka ng tatayo sa puwang, at gusto kong sumagot: narito ako. Patawarin Mo ako sa mga panahong hindi ko ipinanalangin ang mga taong ibinigay Mo sa akin. Turuan Mo akong itaas ang aking mga kamay para sa aking pastor, mga lider, mga maysakit, mga pagod at mga naliligaw. Kapag napapagod ako, padalhan Mo ako ng Aaron at Hur, at gawin Mo rin akong ganoon para sa iba. Nawa'y maisulong ang aming iglesia sa pakpak ng tapat na panalangin. Sa pangalan ni Hesus, Amen."
    ),
  },
};
